// ===== config_bk300.h    - configuración común para la placa BK300 =====
#include <xc.h>
#include <stdint.h>

#pragma config FOSC = XT     // cristal de 4 MHz
#pragma config WDTE = OFF    // watchdog apagado (se enciende solo en el experimento 7)
#pragma config PWRTE = ON    // espera 72 ms al encender para que el voltaje se estabilice
#pragma config BOREN = ON    // reinicio si el voltaje baja demasiado
#pragma config LVP = OFF     // RB3 como pin normal (programación de bajo voltaje desactivada)
#pragma config CPD = OFF, WRT = OFF, CP = OFF

#define _XTAL_FREQ 4000000UL // necesario para __delay_ms()

// [POR CONFIRMAR] pines de habilitación de latches según el esquemático BK300
#define LED_LE      PORTEbits.RE0
#define LED_LE_TRIS TRISEbits.TRISE0

#include "config_bk300.h"

static void leds_escribir(uint8_t patron) {
    PORTD = ~patron;    // en muchas placas los LEDs encienden con 0 (ánodo común) [POR CONFIRMAR]
    LED_LE = 1;         // el 74HC573 copia el bus
    LED_LE = 0;         // y lo retiene
}

void main(void) {
    ADCON1 = 0x06;         // PORTA y PORTE como digitales
    TRISD = 0x00;          // bus de datos como salida
    LED_LE_TRIS = 0;

    uint8_t patron = 0x01;
    while (1) {
        leds_escribir(patron);
        __delay_ms(150);
        patron = (uint8_t)((patron << 1) | (patron >> 7));      // rotación circular
    }
}

#include "config_bk300.h"

volatile uint16_t ms = 0;
volatile uint8_t bandera_200ms = 0;

void __interrupt() isr(void) {
    if (INTCONbits.T0IF) {
        TMR0 = 6;                      // recargar para el siguiente milisegundo
        INTCONbits.T0IF = 0;
        if (++ms >= 200) {             // 200 ms    ->   5 Hz
            ms = 0;
            bandera_200ms = 1;
        }
    }
}

void main(void) {
    ADCON1 = 0x06;
    TRISBbits.TRISB1 = 0;              // LED de prueba en RB1 [POR CONFIRMAR]
    OPTION_REG = 0b10000001;           // T0CS=0 (reloj interno), PSA=0, PS=001 (1:4), sin pull-ups
    TMR0 = 6;
    INTCONbits.T0IE = 1;
    INTCONbits.GIE = 1;

    while (1) {
        if (bandera_200ms) {
            bandera_200ms = 0;
            PORTBbits.RB1 ^= 1;        // aquí, en la Etapa 4, se leen los sensores a 5 Hz
        }
    }
}

#include "config_bk300.h"

volatile uint8_t paro = 0;

void __interrupt() isr(void) {
    if (INTCONbits.INTF) {             // flanco en RB0
        paro = 1;                      // se atiende en microsegundos, haga lo que haga el programa
        INTCONbits.INTF = 0;
    }
}

void main(void) {
    ADCON1 = 0x06;
    TRISBbits.TRISB0 = 1;              // RB0 entrada (botón a tierra)
    OPTION_REG = 0b00000000;           // RBPU=0 (pull-ups activadas), INTEDG=0 (flanco de bajada)
    INTCONbits.INTE = 1;
    INTCONbits.GIE = 1;

    while (1) {
        if (paro) {
            // reportar a la Jetson "$EST,PARO=1" y encender alarma
            __delay_ms(20);          // antirrebote
            if (PORTBbits.RB0 == 1) // botón liberado
                paro = 0;
        }
    }
}

#include "config_bk300.h"

static void pwm1_ciclo(uint16_t ciclo) {           // 0 ... 1000 ->   0 ... 100 %
    CCPR1L = (uint8_t)(ciclo >> 2);                // 8 bits altos
    CCP1CONbits.CCP1X = (ciclo >> 1) & 1;          // 2 bits bajos
    CCP1CONbits.CCP1Y = ciclo & 1;
}

void main(void) {
    TRISCbits.TRISC2 = 0;        // RC2/CCP1 como salida
    PR2 = 249;
    T2CON = 0b00000101;          // Timer2 encendido, preescalador 1:4
    CCP1CON = 0b00001100;        // modo PWM

    while (1) {
        for (uint16_t c = 0; c <= 1000; c += 10) { pwm1_ciclo(c); __delay_ms(10); }
        for (uint16_t c = 1000; c > 0; c -= 10) { pwm1_ciclo(c); __delay_ms(10); }
    }
}

#include "config_bk300.h"

void putch(char c) {                   // printf() de XC8 usa esta función
    while (!TXSTAbits.TRMT);
    TXREG = c;
}

static char uart_leer(void) {
    while (!PIR1bits.RCIF);
    if (RCSTAbits.OERR) { RCSTAbits.CREN = 0; RCSTAbits.CREN = 1; }       // limpiar desbordamiento
    return RCREG;
}

static void uart_inicio(void) {
    TRISCbits.TRISC6 = 0;              // TX
    TRISCbits.TRISC7 = 1;              // RX
    SPBRG = 25;                       // 9600 baudios con BRGH=1
    TXSTA = 0b00100100;               // TXEN=1, BRGH=1, asíncrono
    RCSTA = 0b10010000;               // SPEN=1, CREN=1
}

void main(void) {
    uart_inicio();
    printf("BK300 lista\r\n");
    char linea[16]; uint8_t n = 0;
    while (1) {
        char c = uart_leer();
        if (c == '\r' || c == '\n') {
            linea[n] = 0;
            if (n) printf("ECO:%s\r\n", linea);      // aquí se interpretan comandos
            n = 0;
        } else if (n < sizeof(linea) - 1) {
            linea[n++] = c;
        }
    }
}

#include "config_bk300.h"

static uint8_t ee_leer(uint8_t dir) {
    EEADR = dir;
    EECON1bits.EEPGD = 0;             // memoria de datos, no de programa
    EECON1bits.RD = 1;
    return EEDATA;
}

static void ee_escribir(uint8_t dir, uint8_t dato) {
    EEADR = dir; EEDATA = dato;
    EECON1bits.EEPGD = 0;
    EECON1bits.WREN = 1;
    uint8_t gie = INTCONbits.GIE;
    INTCONbits.GIE = 0;
    EECON2 = 0x55;                   // secuencia obligatoria de desbloqueo
    EECON2 = 0xAA;
    EECON1bits.WR = 1;
    INTCONbits.GIE = gie;
    while (EECON1bits.WR);           // la escritura tarda unos milisegundos
    EECON1bits.WREN = 0;
}

void main(void) {
    if (ee_leer(0x00) != 0xA5) {      // primera vez: guardar valores de fábrica
        ee_escribir(0x01, 90);        // centro del servo de dirección
        ee_escribir(0x02, 15);        // k x 10
        ee_escribir(0x03, 40);        // zona muerta de motores (%)
        ee_escribir(0x00, 0xA5);      // firma de calibración válida
    }
    uint8_t centro = ee_leer(0x01);
    (void)centro;                     // se usa en el programa real
    while (1);
}

