#include "config_bk300.h"

void main(void) {
    // Preescalador asignado al watchdog, 1:128 -> ~ 18 ms x 128 ~ 2.3 s (valor nominal)
    OPTION_REG = 0b10001111;         // PSA=1 (al WDT), PS=111
    TRISBbits.TRISB1 = 0;

    if (STATUSbits.nTO == 0) {
        // El último reinicio lo provocó el watchdog: registrar el evento
        PORTBbits.RB1 = 1;
    }

    while (1) {
        CLRWDT();                    // "estoy vivo"
        // ... trabajo normal ...
        // Si una rutina se queda trabada y no llega a CLRWDT(), el PIC se reinicia solo
    }
}

#include "config_bk300.h"
#include <stdio.h>
// putch() y uart_inicio() del Programa 5

static uint16_t adc_leer(uint8_t canal) {
    ADCON0 = (uint8_t)(0x41 | (canal << 3));      // seleccionar canal en CHS2:CHS0
    __delay_us(20);                               // tiempo de adquisición del capacitor interno
    ADCON0bits.GO_nDONE = 1;
    while (ADCON0bits.GO_nDONE);
    return ((uint16_t)ADRESH << 8) | ADRESL;
}

void main(void) {
    ADCON1 = 0x82;
    TRISA = 0xFF;
    uart_inicio();
    while (1) {
        uint16_t pot = adc_leer(0);
        uint16_t bat = adc_leer(4);
        uint16_t mv = (uint16_t)((uint32_t)bat * 15000UL / 1023UL); // mV de batería (x3 x 5000)
        printf("$SEN,POT1=%u,VBAT=%u\r\n", pot, mv);
        __delay_ms(200);                                          // 5 Hz
    }
}

static void i2c_inicio_bus(void) {
    TRISCbits.TRISC3 = 1; TRISCbits.TRISC4 = 1; // SCL, SDA como entradas (el MSSP las maneja)
    SSPCON = 0b00101000;       // SSPEN=1, modo maestro I2C
    SSPADD = 9;                // 100 kHz = 4 MHz / (4 x (9 + 1))
    SSPSTAT = 0b10000000;      // control de slew rate desactivado (100 kHz)
}
static void i2c_espera(void) { while ((SSPCON2 & 0x1F) || SSPSTATbits.R_nW); }
static void i2c_start(void) { i2c_espera(); SSPCON2bits.SEN = 1; }
static void i2c_stop(void)   { i2c_espera(); SSPCON2bits.PEN = 1; }
static uint8_t i2c_escribir(uint8_t b) { i2c_espera(); SSPBUF = b; i2c_espera(); return !SSPCON2bits.ACKSTAT; }

static void md22_registro(uint8_t reg, uint8_t valor) {
    i2c_start();
    i2c_escribir(0xB0);        // dirección de 8 bits con W = 0
    i2c_escribir(reg);
    i2c_escribir(valor);
    i2c_stop();
}

// Uso: md22_registro(0, 0);   md22_registro(1, 128 + 40);   md22_registro(2, 128 + 40);

#define SERVO1 PORTCbits.RC1
#define SERVO2 PORTCbits.RC2

volatile uint16_t pulso_us[2] = {1500, 1500};
volatile uint8_t fase = 0;

static uint16_t grados_a_us(uint8_t grados) {          // 0-180 grados    ->   1000-2000 us
    return (uint16_t)(1000U + (uint32_t)grados * 1000U / 180U);
}

void __interrupt() isr(void) {
    if (PIR1bits.TMR1IF) {
        PIR1bits.TMR1IF = 0;
        uint16_t t;
        switch (fase) {
            case 0: SERVO1 = 1;               t = pulso_us[0]; fase = 1; break;
            case 1: SERVO1 = 0; SERVO2 = 1; t = pulso_us[1]; fase = 2; break;
            default: SERVO2 = 0; t = 20000U - pulso_us[0] - pulso_us[1]; fase = 0; break;
        }
        uint16_t carga = (uint16_t)(65536UL - t);
        TMR1H = (uint8_t)(carga >> 8);
        TMR1L = (uint8_t)carga;
    }
}

void servos_inicio(void) {
    TRISCbits.TRISC1 = 0; TRISCbits.TRISC2 = 0;
    T1CON = 0b00000001;                  // Timer1 encendido, reloj interno, preescalador 1:1
    PIE1bits.TMR1IE = 1;
    INTCONbits.PEIE = 1;
    INTCONbits.GIE = 1;
}
// Uso: pulso_us[1] = grados_a_us(90);   // dirección al centro

static const uint8_t medio_paso[8] = {0x01,0x03,0x02,0x06,0x04,0x0C,0x08,0x09};
// [POR CONFIRMAR] puerto donde la BK300 conecta las 4 entradas del ULN2003
#define FASES_PUERTO PORTB
void pasos(int16_t n) {
    static uint8_t i = 0;
    while (n) {
        i = (uint8_t)((n > 0) ? (i + 1) & 7 : (i + 7) & 7);
        FASES_PUERTO = (FASES_PUERTO & 0xF0) | medio_paso[i];
        __delay_ms(2);
        n += (n > 0) ? -1 : 1;
    }
}

// nodo_sensores.c - PIC16F877A en BK300 como nodo de sensores del robot CPM
// Requiere en config_bk300.h: #pragma config WDTE = ON
#include "config_bk300.h"
#include <stdio.h>

// --- Funciones de los programas del capítulo 7 y 8 (ver secciones 7.7 y 8.3) ---
void     uart_inicio(void);
void     putch(char c);
uint16_t adc_leer(uint8_t canal);
int16_t ds18b20_decimas(void);         // temperatura en décimas de gradosC (implementación 1-Wire)
uint8_t ee_leer(uint8_t dir);

volatile uint8_t tic_200ms = 0, paro_cambio = 0;
volatile uint16_t ms = 0;

void __interrupt() isr(void) {
    if (PIR1bits.TMR2IF) {                       // base de 1 ms con Timer2 (el Timer0 cede su
        PIR1bits.TMR2IF = 0;                     // preescalador al watchdog)
        if (++ms >= 200) { ms = 0; tic_200ms = 1; }
    }
    if (INTCONbits.INTF) {                       // paro de emergencia en RB0
        INTCONbits.INTF = 0;
        paro_cambio = 1;
    }
}

static void trama(const char *cuerpo) {          // agrega $, checksum XOR y fin de línea
    uint8_t cs = 0;
    for (const char *p = cuerpo; *p; p++) cs ^= (uint8_t)*p;
    printf("$%s*%02X\r\n", cuerpo, cs);
}

void main(void) {
    uint8_t por_watchdog = (STATUSbits.nTO == 0);
    ADCON1 = 0x82; TRISA = 0xFF; TRISBbits.TRISB0 = 1;
    OPTION_REG = 0b00001111;   // pull-ups ON, INT por flanco de bajada,
                               // preescalador 1:128 asignado al watchdog (~ 2.3 s nominal)
    PR2 = 249; T2CON = 0b00000101;               // Timer2: 250 x 4 us = 1 ms
    uart_inicio();
    PIE1bits.TMR2IE = 1; INTCONbits.PEIE = 1;
    INTCONbits.INTE = 1; INTCONbits.GIE = 1;

     char buf[48];
     sprintf(buf, "BOOT,FW=1.0,WDT=%u", por_watchdog); trama(buf);

     uint16_t factor = ((uint16_t)ee_leer(0x04) << 8) | ee_leer(0x05);   // x1000
     if (factor < 2500 || factor > 3500) factor = 3000;

     while (1) {
         CLRWDT();
         if (paro_cambio) {
             paro_cambio = 0;
             sprintf(buf, "EST,PARO=%u", PORTBbits.RB0 ? 0 : 1); trama(buf);
         }
         if (tic_200ms) {
             tic_200ms = 0;
             uint32_t mv = (uint32_t)adc_leer(4) * 5000UL / 1023UL * factor / 1000UL;
             int16_t t = ds18b20_decimas();     // en la práctica, alternar conversión y lectura
             uint16_t p = adc_leer(0);
             sprintf(buf, "SEN,VBAT=%lu,TEMP=%d,POT1=%u", (unsigned long)mv, t, p); trama(buf);
         }
         // Aquí se agrega la lectura de comandos RELE/BUZ/CAL sin bloquear
     }
}

/* ============================================================================
 * pic_integral.c - Controlador integral del vehiculo CPM con PIC16F877A
 * Diseno de conexion de circuito 5 (predecesor del Arduino Mega).
 * Compilador: MPLAB XC8. Cristal: 4 MHz (Tcy = 1 us): cada instruccion toma
 * 1 us, el ADC convierte en ~20 us y el I2C escribe un registro en ~0.3 ms,
 * mientras los comandos de la Jetson llegan a 5 Hz (cada 200 ms).
 *
 * Funciones:
 *   1. Recibe por UART (9600 8N1, MAX232 -> USB-RS232 -> Jetson) el MISMO
 *      protocolo de texto que el firmware del Arduino Mega:
 *        ALL:M1:<v>:M2:<v>:S1:<a>:S2:<a>   STOP_ALL_MOTORS   PING   STATUS
 *      con los mismos rangos (motores 0 o 40-100 %, S1 40-140, S2 40-140) y las
 *      mismas respuestas (OK:M1:..., ERR:RANGE:..., PONG),
 *      y comandos propios del nodo: RELE:<0|1> BUZ:<ms> CAL:VBAT=<mV> CAL:S2C=<grados>
 *   2. Maneja el puente H MD22 por I2C (MSSP maestro, 100 kHz, direccion 0xB0).
 *   3. Genera los pulsos de los servos S2 (direccion, RC1) y S1 (pinzas, RC2)
 *      por software con Timer1, 50 Hz.
 *   4. Mide bateria (AN4), temperatura (DS18B20 en RB5) y pulsos del codificador
 *      (Timer0 como contador en RA4/T0CKI).
 *   5. Atiende el paro de emergencia en RB0/INT (flanco de subida, boton NC):
 *      abre el relevador K1 dentro de la interrupcion y detiene los motores.
 *   6. Seguridad: EN = /P * W * B * T. Vigilante de comunicacion de 500 ms,
 *      watchdog de hardware (preescalador 1:128, ~2.3 s), relevador de corte K1.
 *   7. Publica tramas $BOOT, $SEN (5 Hz) y $EST con checksum XOR, iguales a las
 *      del nodo de sensores, para que el puente de la Jetson no cambie.
 * ============================================================================ */
#include <xc.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#pragma config FOSC = XT, WDTE = ON, PWRTE = ON, BOREN = ON, LVP = OFF
#pragma config CPD = OFF, WRT = OFF, CP = OFF
#define _XTAL_FREQ 4000000UL

/* ---------- Pines ---------- */
#define SERVO_S2   PORTCbits.RC1      /* direccion Ackermann (HS-805BB) */
#define SERVO_S1   PORTCbits.RC2      /* pinzas frontales               */
#define RELE_K1    PORTEbits.RE1      /* 1 = potencia de motores habilitada */
#define ZUMBADOR   PORTEbits.RE2
#define LED_VIDA   PORTDbits.RD0
#define LED_PARO   PORTDbits.RD1
#define OW_PIN     PORTBbits.RB5      /* DS18B20, pull-up de 4.7 k */
#define OW_TRIS    TRISBbits.TRISB5
#define PARO_PIN   PORTBbits.RB0      /* boton NC a GND: 1 = presionado o cable roto */

/* ---------- Constantes (mismas fuentes de verdad que el Arduino) ---------- */
/* Mismas constantes que el firmware vigente del Arduino (rangos ampliados) */
#define MOTOR_MIN       40            /* % ; 0 = paro, 40-100 = avance       */
#define MOTOR_MAX       100           /* modo 5 usa hasta 100 % en giros    */
#define S2_MIN          40            /* grados: 40 = derecha maxima        */
#define S2_MAX          140           /* 140 = izquierda maxima (S2>90 = izq)*/
#define S1_MIN          40            /* pinzas: 40 abiertas (boton A)      */
#define S1_MAX          140           /* 140 cerradas (boton B)             */
#define T_VIGILANTE_MS 500u           /* 2.5 periodos del ciclo de 5 Hz (200 ms) */
#define VBAT_MIN_MV     11800u
#define TEMP_MAX_D      600           /* 60.0 C en decimas */
#define MD22_ADDR       0xB0          /* 8 bits (0x58 en 7 bits) */

/* ---------- Estado compartido con las interrupciones ---------- */
volatile uint16_t ms_total = 0, ms_vigilante = 0;
volatile uint8_t tic_200ms = 0, paro_evento = 0;
volatile char     rx_buf[48];                   /* cola circular de recepcion */
volatile uint8_t rx_cab = 0, rx_col = 0;
volatile uint16_t pulso_us[2] = {1500, 1500};      /* [0] = S2, [1] = S1 */
volatile uint8_t fase_servo = 0;
volatile uint16_t enc_desbordes = 0;

/* ---------- Estado del controlador ---------- */
static char     linea[40];
static uint8_t n_linea = 0;
static uint16_t vbat_mv = 0, factor_div = 3000;    /* x1000 */
static int16_t temp_d = 0;
static uint8_t s2_centro = 90, bat_ok = 1, temp_ok = 1, com_ok = 0, paro = 0;
static int8_t   m1_actual = 0, m2_actual = 0;

/* ============================== Interrupciones ============================ */
void __interrupt() isr(void) {
    if (PIR1bits.TMR1IF) {                          /* pulsos de servo, 50 Hz */
        PIR1bits.TMR1IF = 0;
        uint16_t t;
        switch (fase_servo) {
            case 0: SERVO_S2 = 1;                   t = pulso_us[0]; fase_servo = 1; break;
            case 1: SERVO_S2 = 0; SERVO_S1 = 1;     t = pulso_us[1]; fase_servo = 2; break;
            default: SERVO_S1 = 0; t = 20000u - pulso_us[0] - pulso_us[1];
                     fase_servo = 0; break;         /* fase de reposo: >= 16 ms */
        }
        uint16_t carga = (uint16_t)(65536UL - t + 12u); /* +12 us: latencia de entrada */
        TMR1H = (uint8_t)(carga >> 8); TMR1L = (uint8_t)carga;
    }
    if (PIR1bits.TMR2IF) {                         /* base de 1 ms */
        PIR1bits.TMR2IF = 0;
        ms_total++;
        if (ms_vigilante < 0xFFFF) ms_vigilante++;
        static uint8_t c200 = 0;
        if (++c200 >= 200) { c200 = 0; tic_200ms = 1; }
    }
    if (PIR1bits.RCIF) {                           /* recepcion serie sin perder bytes */
        if (RCSTAbits.OERR) { RCSTAbits.CREN = 0; RCSTAbits.CREN = 1; }
        char ch = RCREG; uint8_t sig = (uint8_t)((rx_cab + 1) % sizeof(rx_buf));
        if (sig != rx_col) { rx_buf[rx_cab] = ch; rx_cab = sig; }
    }
    if (INTCONbits.INTF) {                         /* paro: corte por hardware inmediato */
        INTCONbits.INTF = 0; RELE_K1 = 0; paro_evento = 1;
    }
    if (INTCONbits.T0IF) { INTCONbits.T0IF = 0; enc_desbordes++; }
}

/* ================================ UART ==================================== */
void putch(char c) { while (!TXSTAbits.TRMT); TXREG = c; }
static void uart_inicio(void) {
    TRISCbits.TRISC6 = 0; TRISCbits.TRISC7 = 1;
    SPBRG = 25; TXSTA = 0x24; RCSTA = 0x90;         /* 9600 baudios, BRGH = 1 */
}
static void trama(const char *cuerpo) {            /* $cuerpo*CS\r\n, CS = XOR */
    uint8_t cs = 0;
    for (const char *p = cuerpo; *p; p++) cs ^= (uint8_t)*p;
    printf("$%s*%02X\r\n", cuerpo, cs);
}

/* ============================ I2C y MD22 ================================== */
static void i2c_inicio(void) {
    TRISCbits.TRISC3 = 1; TRISCbits.TRISC4 = 1;
    SSPCON = 0x28; SSPADD = 9; SSPSTAT = 0x80;      /* maestro, 100 kHz */
}
static void i2c_espera(void) { while ((SSPCON2 & 0x1F) || SSPSTATbits.R_nW); }
static uint8_t i2c_byte(uint8_t b) { i2c_espera(); SSPBUF = b; i2c_espera(); return !SSPCON2bits.ACKSTAT; }
static uint8_t md22_reg(uint8_t reg, uint8_t valor) {
    uint8_t ok;
    i2c_espera(); SSPCON2bits.SEN = 1;
    ok = i2c_byte(MD22_ADDR);
    ok &= i2c_byte(reg);
    ok &= i2c_byte(valor);
    i2c_espera(); SSPCON2bits.PEN = 1;
    return ok;                                       /* 1 si hubo ACK en todo */
}
static uint8_t pct_a_md22(int8_t p) { return (uint8_t)(128 + ((int16_t)p * 127) / 100); }
static uint8_t motor_valido(int16_t v) {            /* igual que el Arduino: */
    return (v == 0) || (v >= MOTOR_MIN && v <= MOTOR_MAX);    /* 0 o 50-80 % */
}
static void motores(int8_t m1, int8_t m2) {
    m1_actual = m1; m2_actual = m2;
    md22_reg(1, pct_a_md22(m1));
    md22_reg(2, pct_a_md22(m2));
}

/* ============================== Servos ==================================== */
static uint16_t grados_a_us(uint8_t g) { return (uint16_t)(1000u + (uint32_t)g * 1000u / 180u); }
static uint8_t limitar(int16_t v, uint8_t lo, uint8_t hi) { return (uint8_t)(v < lo ? lo : (v > hi ? hi : v)); }
static void servos(uint8_t s1, uint8_t s2) {
    int16_t s2c = (int16_t)s2 + ((int16_t)s2_centro - 90);    /* calibracion del centro */
    uint16_t p2 = grados_a_us(limitar(s2c, S2_MIN, S2_MAX));
    uint16_t p1 = grados_a_us(limitar(s1, S1_MIN, S1_MAX));
    INTCONbits.GIE = 0; pulso_us[0] = p2; pulso_us[1] = p1; INTCONbits.GIE = 1;
}
static void parar_todo(void) { motores(0, 0); servos(90, 90); }

/* ============================== EEPROM ==================================== */
static uint8_t ee_leer(uint8_t d) { EEADR = d; EECON1bits.EEPGD = 0; EECON1bits.RD = 1; return EEDATA; }
static void ee_escribir(uint8_t d, uint8_t v) {
    EEADR = d; EEDATA = v; EECON1bits.EEPGD = 0; EECON1bits.WREN = 1;
    uint8_t g = INTCONbits.GIE; INTCONbits.GIE = 0;
    EECON2 = 0x55; EECON2 = 0xAA; EECON1bits.WR = 1;
    INTCONbits.GIE = g; while (EECON1bits.WR); EECON1bits.WREN = 0;
}
static void calibracion_cargar(void) {
    if (ee_leer(0x00) != 0xA5) {                    /* valores de fabrica */
        ee_escribir(0x01, 90); ee_escribir(0x04, 3000 >> 8); ee_escribir(0x05, 3000 & 0xFF);
        ee_escribir(0x00, 0xA5);
    }
    s2_centro = ee_leer(0x01);
    factor_div = ((uint16_t)ee_leer(0x04) << 8) | ee_leer(0x05);
    if (factor_div < 2500 || factor_div > 3500) factor_div = 3000;
}

/* ============================== Sensores ================================== */
static uint16_t adc_leer(uint8_t canal) {
    ADCON0 = (uint8_t)(0x41 | (canal << 3)); __delay_us(20);
    ADCON0bits.GO_nDONE = 1; while (ADCON0bits.GO_nDONE);
    return ((uint16_t)ADRESH << 8) | ADRESL;
}
/* 1-Wire: interrupciones deshabilitadas solo durante cada ranura (<= 70 us) */
static uint8_t ow_reset(void) {
    uint8_t presencia;
    OW_PIN = 0; OW_TRIS = 0; __delay_us(480); OW_TRIS = 1;
    __delay_us(70); presencia = !OW_PIN; __delay_us(410);
    return presencia;
}
static void ow_bit_w(uint8_t b) {
    INTCONbits.GIE = 0;
    OW_PIN = 0; OW_TRIS = 0;
    if (b) { __delay_us(6); OW_TRIS = 1; __delay_us(64); }
    else   { __delay_us(60); OW_TRIS = 1; __delay_us(10); }
    INTCONbits.GIE = 1;
}
static uint8_t ow_bit_r(void) {
    uint8_t b;
    INTCONbits.GIE = 0;
    OW_PIN = 0; OW_TRIS = 0; __delay_us(3); OW_TRIS = 1; __delay_us(9);
    b = OW_PIN; INTCONbits.GIE = 1; __delay_us(55);
    return b;
}
static void ow_byte_w(uint8_t v) { for (uint8_t i = 0; i < 8; i++) { ow_bit_w(v & 1); v >>= 1; } }
static uint8_t ow_byte_r(void) { uint8_t v = 0; for (uint8_t i = 0; i < 8; i++) { v >>= 1; if (ow_bit_r()) v |= 0x80; } return v; }

/* Maquina de estados del DS18B20: solo actua durante la fase de reposo de los
   servos y si quedan mas de 4 ms antes del siguiente pulso, de modo que las
   ranuras 1-Wire (con interrupciones deshabilitadas) no deforman los pulsos. */
static void ds18b20_tarea(void) {
    static uint8_t estado = 0; static uint16_t t0 = 0;
    uint16_t tmr1;
    INTCONbits.GIE = 0; tmr1 = ((uint16_t)TMR1H << 8) | TMR1L; INTCONbits.GIE = 1;
    if (fase_servo != 0 || (uint16_t)(0u - tmr1) < 4000u) return;
    if (estado == 0) {                               /* iniciar conversion */
        if (ow_reset()) { ow_byte_w(0xCC); ow_byte_w(0x44); t0 = ms_total; estado = 1; }
    } else if ((uint16_t)(ms_total - t0) >= 750u) { /* leer resultado */
        if (ow_reset()) {
            ow_byte_w(0xCC); ow_byte_w(0xBE);
            uint8_t lsb = ow_byte_r(), msb = ow_byte_r();
            int16_t crudo = (int16_t)(((uint16_t)msb << 8) | lsb);
            temp_d = (int16_t)(((int32_t)crudo * 10) / 16);        /* decimas de C */
        }
        estado = 0;
    }
}

/* ========================== Intérprete de comandos ======================== */
static const char *leer_entero(const char *p, int16_t *v) {
    int16_t s = 1, r = 0;
    if (*p == '-') { s = -1; p++; }
    if (*p < '0' || *p > '9') return 0;
    while (*p >= '0' && *p <= '9') { r = (int16_t)(r * 10 + (*p - '0')); p++; }
    *v = (int16_t)(s * r);
    return p;
}
static uint8_t interpretar_all(const char *c) {     /* ALL:M1:a:M2:b:S1:c:S2:d */
    int16_t m1, m2, a1, a2;
    if (strncmp(c, "ALL:M1:", 7)) return 0;
    if (!(c = leer_entero(c + 7, &m1)) || strncmp(c, ":M2:", 4)) return 0;
    if (!(c = leer_entero(c + 4, &m2)) || strncmp(c, ":S1:", 4)) return 0;
    if (!(c = leer_entero(c + 4, &a1)) || strncmp(c, ":S2:", 4)) return 0;
    if (!(c = leer_entero(c + 4, &a2))) return 0;
    if (!motor_valido(m1) || !motor_valido(m2) ||        /* trama completa o nada */
        a1 < S1_MIN || a1 > S1_MAX || a2 < S2_MIN || a2 > S2_MAX) {
        printf("ERR:RANGE:M1:%d:M2:%d:S1:%d:S2:%d\r\n", m1, m2, a1, a2);
        return 3;
    }
    if (paro || !bat_ok || !temp_ok) { parar_todo(); return 2; }    /* bloqueado */
    servos((uint8_t)a1, (uint8_t)a2);
    motores((int8_t)m1, (int8_t)m2);
    printf("OK:M1:%d:M2:%d:S1:%d:S2:%d\r\n", m1, m2, a1, a2);    /* eco como el Mega */
    return 1;
}
static void comando(const char *c) {
    uint8_t ok = 0; int16_t v;
    if (!strncmp(c, "ALL:", 4)) {
        uint8_t r = interpretar_all(c);
        if (r == 2) { printf("BLOQUEADO\r\n"); ms_vigilante = 0; return; }
        if (r == 1) { ms_vigilante = 0; com_ok = 1; return; } /* eco ya enviado */
        if (r == 3) return;                                      /* ERR:RANGE enviado */
        ok = 0;
    }
    else if (!strcmp(c, "STOP_ALL_MOTORS") || !strcmp(c, "STOP_ALL")) { parar_todo(); ok = 1; }
    else if (!strcmp(c, "PING")) { printf("PONG\r\n"); ms_vigilante = 0; return; }
    else if (!strcmp(c, "STATUS")) {
        printf("M1=%d M2=%d VBAT=%u TEMP=%d PARO=%u\r\n", m1_actual, m2_actual, vbat_mv, temp_d, paro);
        ok = 1;
    }
    else if (!strncmp(c, "RELE:", 5)) { RELE_K1 = (c[5] == '1') && !paro; ok = 1; }
    else if (!strncmp(c, "BUZ:", 4) && leer_entero(c + 4, &v)) {
        if (v > 500) v = 500;
        ZUMBADOR = 1; while (v-- > 0) { __delay_ms(1); CLRWDT(); } ZUMBADOR = 0; ok = 1;
    }
    else if (!strncmp(c, "CAL:VBAT=", 9) && leer_entero(c + 9, &v) && vbat_mv) {
        /* nuevo factor = factor * V_real / V_medido */
        factor_div = (uint16_t)(((uint32_t)factor_div * (uint16_t)v) / vbat_mv);
        ee_escribir(0x04, factor_div >> 8); ee_escribir(0x05, factor_div & 0xFF); ok = 1;
    }
    else if (!strncmp(c, "CAL:S2C=", 8) && leer_entero(c + 8, &v) && v >= 70 && v <= 110) {
        s2_centro = (uint8_t)v; ee_escribir(0x01, s2_centro); ok = 1;
    }
    printf(ok ? "OK\r\n" : "ERR\r\n");
    if (ok) { ms_vigilante = 0; com_ok = 1; }
}
static void uart_tarea(void) {
    while (rx_col != rx_cab) {
        char ch = rx_buf[rx_col]; rx_col = (uint8_t)((rx_col + 1) % sizeof(rx_buf));
        if (ch == '\r' || ch == '\n') {
            if (n_linea) { linea[n_linea] = 0; comando(linea); n_linea = 0; }
        } else if (n_linea < sizeof(linea) - 1) linea[n_linea++] = ch;
        else n_linea = 0;                           /* linea demasiado larga: descartar */
    }
}

/* ================================ main ==================================== */
void main(void) {
    uint8_t por_wdt = (STATUSbits.nTO == 0);
    char buf[56];

    ADCON1 = 0x82;                                   /* AN0-AN4 analogicas, resultado a la derecha */
    TRISA = 0xFF; TRISB = 0xFF; TRISD = 0x00; TRISE = 0x00;
    TRISCbits.TRISC1 = 0; TRISCbits.TRISC2 = 0;
    PORTD = 0; RELE_K1 = 0; ZUMBADOR = 0;
    OPTION_REG = 0x6F;   /* pull-ups ON, INT en flanco de SUBIDA (boton NC a GND: al
                            presionarlo o romperse el cable, RB0 sube), Timer0 contador en
                            T0CKI, preescalador 1:128 asignado al watchdog (~2.3 s) */
    T1CON = 0x01;                                    /* Timer1: 1 us por cuenta (servos) */
    PR2 = 249; T2CON = 0x05;                         /* Timer2: 250 x 4 us = 1 ms */
    uart_inicio(); i2c_inicio(); calibracion_cargar();
    PIE1bits.TMR1IE = 1; PIE1bits.TMR2IE = 1; PIE1bits.RCIE = 1; INTCONbits.PEIE = 1;
    INTCONbits.INTE = 1; INTCONbits.T0IE = 1; INTCONbits.GIE = 1;

    md22_reg(0, 0);                                 /* modo 0: 0 reversa, 128 paro, 255 avance */
    md22_reg(3, 10);                                /* aceleracion gradual */
    parar_todo();
    sprintf(buf, "BOOT,FW=PIC-1.0,WDT=%u,MD22=%u", por_wdt, md22_reg(1, 128)); trama(buf);
    paro = PARO_PIN;          /* K1 arranca abierto: la Jetson lo habilita con RELE:1 */

    uint8_t bajas = 0;
    while (1) {
        CLRWDT();
        uart_tarea();
        ds18b20_tarea();

        if (paro_evento) { paro_evento = 0; parar_todo(); }    /* K1 ya se abrio en la ISR */
        uint8_t p = PARO_PIN;                       /* cambio de estado con antirrebote */
        if (p != paro) {
            __delay_ms(20);
            if (PARO_PIN == p) {
                paro = p;
                if (paro) { RELE_K1 = 0; parar_todo(); }    /* al liberar se requiere RELE:1 */
                sprintf(buf, "EST,PARO=%u", paro); trama(buf);
            }
        }
        LED_PARO = paro;

        /* Vigilante de comunicacion: sin comandos validos en 500 ms -> paro */
        if (com_ok && ms_vigilante > T_VIGILANTE_MS) {
            parar_todo(); com_ok = 0;
            printf("WARN timeout: motores detenidos\r\n");
        }

        if (tic_200ms) {                            /* 5 Hz: medir y reportar */
            tic_200ms = 0; LED_VIDA ^= 1;
            vbat_mv = (uint16_t)(((uint32_t)adc_leer(4) * 5000UL / 1023UL) * factor_div / 1000UL);
            bajas = (vbat_mv < VBAT_MIN_MV) ? (uint8_t)(bajas < 5 ? bajas + 1 : 5) : 0;
            bat_ok = (bajas < 5);                   /* 1 s sostenido por debajo */
            temp_ok = (temp_d <= TEMP_MAX_D);
            if ((!bat_ok || !temp_ok) && (m1_actual || m2_actual)) parar_todo();

            uint16_t enc = ((uint16_t)enc_desbordes << 8) | TMR0;   /* pulsos acumulados */
            uint8_t en = (uint8_t)(!paro && com_ok && bat_ok && temp_ok);
            sprintf(buf, "SEN,VBAT=%u,TEMP=%d,ENC=%u,EN=%u", vbat_mv, temp_d, enc, en);
            trama(buf);
        }
    }
}

