#include <Wire.h>

const uint8_t MD22_DIR   = 0x58;      // 0xB0 >> 1 (formato de 7 bits de Wire)
const uint8_t REG_MODO   = 0;
const uint8_t REG_VEL1   = 1;
const uint8_t REG_VEL2   = 2;
const uint8_t REG_ACEL   = 3;
const uint8_t REG_VERSION = 7;

int vel1 = 0, vel2 = 0;               // porcentaje -100 ... +100

void md22Escribir(uint8_t reg, uint8_t valor) {
  Wire.beginTransmission(MD22_DIR);
  Wire.write(reg);
  Wire.write(valor);
  Wire.endTransmission();
}

int md22Leer(uint8_t reg) {
  Wire.beginTransmission(MD22_DIR);
  Wire.write(reg);
  if (Wire.endTransmission() != 0) return -1;         // sin respuesta
  Wire.requestFrom(MD22_DIR, (uint8_t)1);
  return Wire.available() ? Wire.read() : -1;
}

uint8_t porcentajeAValor(int p) {                     // modo 0: 0 = reversa, 128 = paro, 255 = avance
  p = constrain(p, -100, 100);
  return (uint8_t)(128 + (long)p * 127 / 100);
}

void aplicar() {
  md22Escribir(REG_VEL1, porcentajeAValor(vel1));
  md22Escribir(REG_VEL2, porcentajeAValor(vel2));
}

void setup() {
  Serial.begin(115200);
  Wire.begin();
  delay(100);
  md22Escribir(REG_MODO, 0);
  md22Escribir(REG_ACEL, 10);    // rampa suave [POR CONFIRMAR valor ideal en la hoja de datos]
  vel1 = vel2 = 0; aplicar();
  Serial.println(F("MD22 - comandos: PING, STATUS, STOP, M1:<-100..100>, M2:<-100..100>"));
}

void loop() {
  if (!Serial.available()) return;
  String c = Serial.readStringUntil('\n'); c.trim(); c.toUpperCase();

    if (c == "PING") {
      int v = md22Leer(REG_VERSION);
      if (v < 0) Serial.println(F("ERR MD22 no responde"));
      else { Serial.print(F("OK MD22 version ")); Serial.println(v); }
    } else if (c == "STATUS") {
      Serial.print(F("M1=")); Serial.print(vel1); Serial.print(F("% M2=")); Serial.print(vel2); Serial.println('%');
    } else if (c == "STOP") {
      vel1 = vel2 = 0; aplicar(); Serial.println(F("OK STOP"));
    } else if (c.startsWith("M1:")) {
      vel1 = c.substring(3).toInt(); aplicar(); Serial.println(F("OK M1"));
    } else if (c.startsWith("M2:")) {
      vel2 = c.substring(3).toInt(); aplicar(); Serial.println(F("OK M2"));
    } else {
      Serial.println(F("ERR comando"));
    }
}

// Potenciómetro en A0, divisor de batería (20k/10k) en A1, HC-SR04 en D7 (TRIG) y D8 (ECHO)
const int PIN_POT = A0, PIN_BAT = A1, PIN_TRIG = 7, PIN_ECHO = 8;
const float FACTOR_DIVISOR = 3.0;      // calibrar contra multímetro

float leerBateria() {
  long suma = 0;
  for (int i = 0; i < 8; i++) suma += analogRead(PIN_BAT);   // promedio de 8 lecturas
  return (suma / 8.0) * 5.0 / 1023.0 * FACTOR_DIVISOR;
}

long leerDistanciaCm() {
  digitalWrite(PIN_TRIG, LOW); delayMicroseconds(2);
  digitalWrite(PIN_TRIG, HIGH); delayMicroseconds(10);
  digitalWrite(PIN_TRIG, LOW);
  unsigned long t = pulseIn(PIN_ECHO, HIGH, 30000UL);        // máx. 30 ms (~ 5 m)
  return t ? (long)(t / 58) : -1;
}

void setup() { Serial.begin(115200); pinMode(PIN_TRIG, OUTPUT); pinMode(PIN_ECHO, INPUT); }

void loop() {
  Serial.print(F("$SEN,POT1=")); Serial.print(analogRead(PIN_POT));
  Serial.print(F(",VBAT="));     Serial.print(leerBateria(), 2);
  Serial.print(F(",DIST="));     Serial.println(leerDistanciaCm());
  delay(200);                                                  // 5 Hz
}

#include <Wire.h>
#include <Servo.h>

// ---------- Constantes de rango (únicas fuentes de verdad en el firmware) ----------
const int MOTOR_MIN = 40, MOTOR_MAX = 100;     // % (0 = paro)
const int S2_MIN    = 40, S2_MAX     = 140;    // dirección
const int S1_MIN    = 0,   S1_MAX    = 180;    // auxiliar
const unsigned long TIEMPO_SIN_COMANDOS_MS = 500;    // 2.5 periodos de 5 Hz

const uint8_t MD22 = 0x58;
Servo s1, s2;
unsigned long ultimoComando = 0;
bool detenidoPorTimeout = false;

void md22(uint8_t reg, uint8_t v) { Wire.beginTransmission(MD22); Wire.write(reg); Wire.write(v); Wire.endTransmission(); }
uint8_t pct(int p) { return (uint8_t)(128 + (long)p * 127 / 100); }

int validarMotor(int v) {                       // 0 permitido; si no, |v| entre MIN y MAX
  if (v == 0) return 0;
  int s = (v > 0) ? 1 : -1;
  return s * constrain(abs(v), MOTOR_MIN, MOTOR_MAX);
}

void pararTodo() { md22(1, 128); md22(2, 128); s2.write(90); }

void aplicar(int m1, int m2, int a1, int a2) {
  md22(1, pct(validarMotor(m1)));
  md22(2, pct(validarMotor(m2)));
  s1.write(constrain(a1, S1_MIN, S1_MAX));
  s2.write(constrain(a2, S2_MIN, S2_MAX));
}

// Formato: ALL:M1:<v>:M2:<v>:S1:<a>:S2:<a>
bool interpretarALL(const String& c) {
  int m1, m2, a1, a2;
  if (sscanf(c.c_str(), "ALL:M1:%d:M2:%d:S1:%d:S2:%d", &m1, &m2, &a1, &a2) != 4) return false;
  aplicar(m1, m2, a1, a2);
  return true;
}

void setup() {
  Serial.begin(115200);
  Wire.begin();
  md22(0, 0); md22(3, 10);
  s1.attach(8); s2.attach(9);   // 8: pinzas, 9: dirección
  pararTodo();
  Serial.println(F("CPM actuadores listo"));
  ultimoComando = millis();
}

void loop() {
  if (Serial.available()) {
    String c = Serial.readStringUntil('\n'); c.trim();
    bool ok = false;
    if (c.startsWith("ALL:"))            ok = interpretarALL(c);
    else if (c == "STOP_ALL_MOTORS")    { pararTodo(); ok = true; }
    else if (c == "PING")               { ok = true; }
    Serial.println(ok ? F("OK") : F("ERR"));
    if (ok) { ultimoComando = millis(); detenidoPorTimeout = false; }
  }
    // Watchdog de comunicación: si la Jetson o el Wi-Fi fallan, el robot se detiene solo
    if (!detenidoPorTimeout && millis() - ultimoComando > TIEMPO_SIN_COMANDOS_MS) {
      pararTodo();
      detenidoPorTimeout = true;
      Serial.println(F("WARN timeout: motores detenidos"));
    }
}

// Se llama al final de setup(): verifica cada actuador antes de aceptar comandos
bool autodiagnostico() {
  bool ok = true;
  Wire.beginTransmission(0x58); Wire.write(7);
  if (Wire.endTransmission() != 0) { Serial.println(F("DIAG MD22: FALLA")); ok = false; }
  else Serial.println(F("DIAG MD22: OK"));

    s2.write(80); delay(300); s2.write(100); delay(300); s2.write(90);   // pequeño movimiento visible
    Serial.println(F("DIAG S2: verificar movimiento 80-100-90"));
    return ok;
}

/*
 * arduino_actuator_controller_expanded_ranges.ino - VERSION VIGENTE (abril 2026)
 * [RECONSTRUIDO] para la tesis a partir de arduino_actuator_controller_reduced_output.ino:
 * el firmware de rangos ampliados difiere solo en las constantes de validacion
 * (motores 0 o 40-100 %, servo S2 40-140 grados), que son la unica fuente de verdad.
 * Convencion confirmada en las corridas de abril: M1 = motor IZQUIERDO, M2 = DERECHO;
 * S2 > 90 = giro a la IZQUIERDA (140 = izquierda maxima, 40 = derecha maxima).
 * Tasas: el ATmega2560 corre a 16 MHz (62.5 ns por ciclo); loop() se repite
 * decenas de miles de veces por segundo, el I2C del MD22 va a 100 kHz (~0.3 ms
 * por escritura), la UART a 115200 Bd (~87 us por caracter) y la biblioteca Servo
 * genera pulsos de 50 Hz con resolucion de 0.5 us. Los comandos llegan a 5 Hz.
 *
 * Arduino Dual Servo + MD22 Motor Controller for Meta Quest 3 Integration
 * Receives commands via Serial from Jetson Nano
 * Controls:
 *   - Servo1 on Pin 8 (Range: 40-140 degrees) - Controlled by RIGHT A/B buttons
 *   - Servo2 on Pin 9 (Range: 40-140 degrees) - Controlled by RIGHT joystick X
 *   - MD22 Motor1 via I2C (Speed: 0 or 40-100% forward) - Controlled by LEFT joystick Y
 *   - MD22 Motor2 via I2C (Speed: 0 or 40-100% forward) - Controlled by LEFT joystick Y
 *
 * Hardware:
 * - Arduino Mega 2560 (recommended for I2C on pins 20/21)
 * - Servo1 motor connected to Pin 8 (40-140° range)
 * - Servo2 motor connected to Pin 9 (40-140° range)
* - MD22 H-bridge connected via I2C (SDA pin 20, SCL pin 21)
* - USB connection to Jetson Nano
*
* MD22 I2C Connection:
* - Arduino Pin 20 (SDA) -> MD22 SDA
* - Arduino Pin 21 (SCL) -> MD22 SCL
* - Arduino GND -> MD22 GND
* - External 12V -> MD22 motor power
*
* ===== SERIAL COMMANDS (115200 baud) =====
*
* ** DIFFERENTIAL DRIVE COMMAND (RECOMMENDED for Quest 3!) **
*   ALL:M1:{motor1}:M2:{motor2}:S1:{servo1}:S2:{servo2}
*     - Individual control of left/right motors for differential drive
*     - Example: ALL:M1:60:M2:70:S1:90:S2:110
*     - Response: OK:A:M1:60:M2:70:S1:90:S2:110
*     - M1 (LEFT motor): 0 or 40-100 (0=stop, 40-100=forward %)
*     - M2 (RIGHT motor): 0 or 40-100 (0=stop, 40-100=forward %)
*     - Servo1: 40-140 (gripper angle in degrees)
*     - Servo2: 40-140 (steering angle in degrees; 140 = full LEFT)
*
* ** COMBINED COMMAND (Legacy - same speed both motors) **
*   ALL:M{motor}:S1:{servo1}:S2:{servo2}
*     - Single atomic command for all actuators (both motors same speed)
*     - Example: ALL:M65:S1:90:S2:110
*     - Response: OK:A:M65:S1:90:S2:110
*     - Motor: 0 or 40-100 (0=stop, 40-100=forward %)
*     - Servo1: 40-140 (gripper angle in degrees)
*     - Servo2: 40-140 (steering angle in degrees; 140 = full LEFT)
*
* ** INDIVIDUAL COMMANDS (Legacy - for manual testing) **
*   SERVO1:angle      - Set servo1 to angle (40-140 degrees)
*     Example: SERVO1:90 -> Response: OK:S1:90
*
*   SERVO2:angle      - Set servo2 to angle (40-140 degrees)
*     Example: SERVO2:110 -> Response: OK:S2:110
*
*   MOTORS:speed      - Set both motors to same speed (0 or 40-100%)
*     Example: MOTORS:65 -> Response: OK:M65
*
*   MOTOR1:speed      - Set motor1 (LEFT) speed (0 or 40-100%)
*   MOTOR2:speed      - Set motor2 (RIGHT) speed (0 or 40-100%)
*
*   M1_STOP           - Stop motor1
*   M2_STOP           - Stop motor2
*   STOP_ALL_MOTORS   - Stop both motors
*
*   SERVO1_CENTER     - Center servo1 to 90 degrees
*   SERVO2_CENTER     - Center servo2 to 90 degrees
*
*   PING              - Respond with PONG (connection test)
*   STATUS            - Report current state of all actuators
*
* ===== TESTING IN SERIAL MONITOR (115200 baud) =====
*
* ** DIFFERENTIAL DRIVE TESTS **
*
* 1. Stop everything:
*    ALL:M1:0:M2:0:S1:90:S2:90
*
* 2. Straight forward at 65%:
*    ALL:M1:65:M2:65:S1:90:S2:90
*
* 3. Turn left (M1 = left motor slower, M2 faster), S2 > 90:
*    ALL:M1:60:M2:70:S1:90:S2:110
*
* 4. Turn right (M2 = right motor slower, M1 faster), S2 < 90:
*    ALL:M1:70:M2:60:S1:90:S2:70
*
* 5. Sharp left turn (mode 5, confirmed in April runs):
*    ALL:M1:50:M2:100:S1:90:S2:140
*
* 6. Sharp right turn (mode 5, confirmed in April runs):
*    ALL:M1:100:M2:50:S1:90:S2:40
*
* 7. Test gripper open + differential right turn:
*    ALL:M1:60:M2:70:S1:40:S2:110
*
* 8. Test gripper closed + differential left turn:
*    ALL:M1:70:M2:60:S1:140:S2:70
*
* ** LEGACY TESTS (same speed both motors) **
*
* 9. Stop everything (legacy format):
*    ALL:M0:S1:90:S2:90
*
* 10. Both motors 65% (legacy format):
*     ALL:M65:S1:90:S2:90
*
* 11. Check status:
*     STATUS
*
* 12. Test connection:
*     PING
*     (Should respond: PONG)
*
* ===== EXPECTED RESPONSES =====
*
* Differential ALL:   OK:A:M1:{motor1}:M2:{motor2}:S1:{servo1}:S2:{servo2}
* Legacy ALL:         OK:A:M{motor}:S1:{servo1}:S2:{servo2}
* MOTORS command:     OK:M{speed}
* SERVO1 command:     OK:S1:{angle}
* SERVO2 command:     OK:S2:{angle}
* ERROR:              ERROR: {description}
*
*/

#include <Servo.h>
#include <Wire.h>

// Pin definitions
const int SERVO1_PIN = 8;     // RIGHT A/B buttons - servo control
const int SERVO2_PIN = 9;     // RIGHT joystick X - steering control
const int LED_PIN = 13;

// MD22 I2C Configuration
const byte MD22_ADDRESS = 0x58;      // Default MD22 I2C address
const byte MD22_MODE_REG = 0x00;     // Mode register
const byte MD22_MOTOR1_REG = 0x01;   // Motor 1 speed register
const byte MD22_MOTOR2_REG = 0x02;   // Motor 2 speed register
const byte MD22_ACCELERATION_REG = 0x03; // Acceleration register
const byte MD22_VERSION_REG = 0x07; // Version register

// MD22 Speed constants (Mode 0: 0=full reverse, 128=stop, 255=full forward)
const byte MD22_STOP = 128;
const byte MD22_MAX_FORWARD = 255;
const byte MD22_MAX_REVERSE = 0;

// Motor speed limits: 0 or 40-100% (modes 1-3 send 50-80%, mode 5 sends 50-100%)
const int MOTOR_MIN_PERCENT = 40; // [RECONSTRUIDO] below 40% the vehicle stalls
const int MOTOR_MAX_PERCENT = 100; // [RECONSTRUIDO] mode 5 uses up to 100% in sharp turns

// Servo objects
Servo servo1; // Pin 8 - RIGHT A/B button control
Servo servo2; // Pin 9 - RIGHT joystick X control (steering)

// Servo range limits
const int SERVO1_MIN = 40;
const int SERVO1_MAX = 140;
const int SERVO2_MIN = 40;      // [RECONSTRUIDO] full RIGHT (mode 5)
const int SERVO2_MAX = 140;     // [RECONSTRUIDO] full LEFT (mode 5)

// State variables
int currentServo1Angle = 90;           // Current servo1 position
int currentServo2Angle = 90;           // Current servo2 position
int currentMotor1Speed = 0;            // Current motor1 (LEFT) speed (0 or 40-100%)
int currentMotor2Speed = 0;            // Current motor2 (RIGHT) speed (0 or 40-100%)
bool servo1Attached = false;
bool servo2Attached = false;
bool md22Available = false;
byte md22SoftwareVersion = 0;

// Command buffer
String inputString = "";
boolean stringComplete = false;

void setup() {
  // Initialize serial communication at 115200 baud
  Serial.begin(115200);
  while (!Serial) {
    ; // Wait for serial port to connect (needed for native USB)
  }

  // Initialize LED
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LED_PIN, LOW);

  // Initialize I2C for MD22
  Wire.begin();
  delay(100);
  initMD22();

  // Attach servos and center them
  attachServo1();
  attachServo2();
  centerServo1();
  centerServo2();

  // Reserve string buffer
  inputString.reserve(200);

  // Send startup message
  Serial.println("Arduino Dual Servo + MD22 Motor Controller Ready");
  Serial.println("Commands: SERVO1:angle, SERVO2:angle, MOTORS:speed, M1_STOP, M2_STOP");
  Serial.println("Servo1 (Pin 8): Range 40-140 degrees (RIGHT A/B buttons)");
  Serial.println("Servo2 (Pin 9): Range 40-140 degrees (RIGHT joystick X - steering)");
  Serial.println("Motors (MD22 via I2C): Speed 0 or 40-100% forward");
  Serial.print("MD22 Status: ");
  Serial.println(md22Available ? "Connected" : "Not detected");
  Serial.print("Current state - Servo1: ");
  Serial.print(currentServo1Angle);
  Serial.print("° | Servo2: ");
  Serial.print(currentServo2Angle);
  Serial.print("° | Motor1: ");
  Serial.print(currentMotor1Speed);
  Serial.print("% | Motor2: ");
  Serial.print(currentMotor2Speed);
  Serial.println("%");

  // Flash LED to indicate ready
  for (int i = 0; i < 3; i++) {
    digitalWrite(LED_PIN, HIGH);
        delay(100);
        digitalWrite(LED_PIN, LOW);
        delay(100);
    }
}

void loop() {
  // A 16 MHz este ciclo se repite decenas de miles de veces por segundo: atiende
  // cada caracter apenas llega (~87 us por caracter a 115200 Bd) aunque las tramas
  // completas lleguen solo cada 200 ms (5 Hz).
  // Read serial commands
  if (Serial.available() > 0) {
    while (Serial.available()) {
      char inChar = (char)Serial.read();

            if (inChar == '\n' || inChar == '\r') {
              if (inputString.length() > 0) {
                stringComplete = true;
              }
            } else {
              inputString += inChar;
            }
        }
    }

    // Process complete commands
    if (stringComplete) {
      processCommand(inputString);
      inputString = "";
      stringComplete = false;
    }

    // Blink LED when servos are active or motors running
    if (servo1Attached || servo2Attached || currentMotor1Speed > 0 || currentMotor2Speed > 0) {
      digitalWrite(LED_PIN, (millis() / 500) % 2);
    }
}

// ========
// MD22 MOTOR CONTROL FUNCTIONS
// ========

void initMD22() {
  /**
   * Initialize MD22 H-bridge controller
   * Set to Mode 0: 0=full reverse, 128=stop, 255=full forward
   * Set acceleration to moderate value
   */
  Serial.println("Initializing MD22...");

    // Test I2C connection
    Wire.beginTransmission(MD22_ADDRESS);
    byte error = Wire.endTransmission();

    if (error == 0) {
      md22Available = true;
      Serial.println(" MD22 found at 0x58");

        // Read software version
        md22SoftwareVersion = readMD22Register(MD22_VERSION_REG);
        Serial.print(" Software version: ");
        Serial.println(md22SoftwareVersion);

        // Set MD22 to Mode 0 (0-255 speed range)
        writeMD22Register(MD22_MODE_REG, 0);
        delay(50);
        byte modeCheck = readMD22Register(MD22_MODE_REG);
        Serial.print(" Mode set to: ");
        Serial.println(modeCheck);

        // Set moderate acceleration (10 = about 1 second to full speed)
        writeMD22Register(MD22_ACCELERATION_REG, 10);
        delay(50);
        Serial.println(" Acceleration set to 10");

        // Stop both motors
        writeMD22Register(MD22_MOTOR1_REG, MD22_STOP);
        writeMD22Register(MD22_MOTOR2_REG, MD22_STOP);
        delay(50);
        Serial.println(" Both motors stopped");

      Serial.println("MD22 initialized successfully!");
    } else {
      md22Available = false;
      Serial.println("WARNING: MD22 not found on I2C bus");
      Serial.println("Check SDA/SCL connections and MD22 power");
      Serial.print("I2C error code: ");
      Serial.println(error);
    }
    Serial.println();
}

void writeMD22Register(byte reg, byte value) {
  /**
   * Write a value to MD22 register via I2C
   */
  Wire.beginTransmission(MD22_ADDRESS);
  Wire.write(reg);
  Wire.write(value);
  Wire.endTransmission();
  // No delay needed - I2C is fast enough
}

byte readMD22Register(byte reg) {
  /**
   * Read a value from MD22 register via I2C
   */
  Wire.beginTransmission(MD22_ADDRESS);
  Wire.write(reg);
  Wire.endTransmission();

    // No delay needed - I2C handles timing
    Wire.requestFrom(MD22_ADDRESS, (byte)1);

    if (Wire.available()) {
      return Wire.read();
    }
    return 0;
}

byte percentToMD22Speed(int percent) {
  /**
   * Convert percentage (50-90) to MD22 speed value
   * 0% -> 128 (stop)
   * 50% -> 192 (halfway forward)
   * 90% -> 242 (90% forward)
   * 100% -> 255 (full forward)
   */

    // Clamp to valid range
    if (percent <= 0) {
      return MD22_STOP;
    }

    percent = constrain(percent, 0, 100);

    // Calculate MD22 speed value
    // Forward range is 128-255 (127 steps)
    // Scale percentage to this range
    int speedRange = (MD22_MAX_FORWARD - MD22_STOP); // 127
    byte md22Speed = MD22_STOP + ((percent * speedRange) / 100);

    return md22Speed;
}

void setMotor1Speed(int percent) {
  /**
   * Set Motor1 speed (0=stop, 40-100% forward)
   */
  if (!md22Available) {
    return; // Silently fail if MD22 not available
  }

    // Clamp to valid range
    percent = constrain(percent, 0, MOTOR_MAX_PERCENT);

    // Convert to MD22 speed value
    byte md22Speed = percentToMD22Speed(percent);

    // Send to MD22 (no verification needed - trust the hardware)
    writeMD22Register(MD22_MOTOR1_REG, md22Speed);
    currentMotor1Speed = percent;
}

void setMotor2Speed(int percent) {
  /**
   * Set Motor2 speed (0=stop, 40-100% forward)
   */
  if (!md22Available) {
    return; // Silently fail if MD22 not available
  }

    // Clamp to valid range
    percent = constrain(percent, 0, MOTOR_MAX_PERCENT);

    // Convert to MD22 speed value
    byte md22Speed = percentToMD22Speed(percent);

    // Send to MD22 (no verification needed - trust the hardware)
    writeMD22Register(MD22_MOTOR2_REG, md22Speed);
    currentMotor2Speed = percent;
}

void setBothMotorsSpeed(int percent) {
  /**
   * Set both motors to the same speed
   * Used for forward motion controlled by LEFT joystick Y
   */
  if (!md22Available) {
    return; // Silently fail if MD22 not available
  }

    // Clamp to valid range
    percent = constrain(percent, 0, MOTOR_MAX_PERCENT);

    // Convert to MD22 speed value
    byte md22Speed = percentToMD22Speed(percent);

    // Send to both motors (no delays - I2C is fast enough)
    writeMD22Register(MD22_MOTOR1_REG, md22Speed);
    writeMD22Register(MD22_MOTOR2_REG, md22Speed);

    currentMotor1Speed = percent;
    currentMotor2Speed = percent;
}

void stopMotor1() {
  /**
   * Stop Motor1
   */
  if (!md22Available) {
    return;
  }

    writeMD22Register(MD22_MOTOR1_REG, MD22_STOP);
    currentMotor1Speed = 0;
}

void stopMotor2() {
  /**
   * Stop Motor2
   */
  if (!md22Available) {
    return;
  }

    writeMD22Register(MD22_MOTOR2_REG, MD22_STOP);
    currentMotor2Speed = 0;
}

void stopAllMotors() {
  /**
   * Stop both motors
   */
  if (!md22Available) {
    return;
  }

    writeMD22Register(MD22_MOTOR1_REG, MD22_STOP);
    writeMD22Register(MD22_MOTOR2_REG, MD22_STOP);

    currentMotor1Speed = 0;
    currentMotor2Speed = 0;
}

// ========
// SERVO CONTROL FUNCTIONS
// ========

void setServo1Angle(int angle) {
  // Ensure servo is attached
  if (!servo1Attached) {
    attachServo1();
  }

    // Clamp angle to valid range for servo1
    angle = constrain(angle, SERVO1_MIN, SERVO1_MAX);

    // Move servo (non-blocking - servo library handles timing)
    servo1.write(angle);
    currentServo1Angle = angle;
}

void setServo2Angle(int angle) {
  // Ensure servo is attached
  if (!servo2Attached) {
    attachServo2();
  }

    // Clamp angle to valid range for servo2
    angle = constrain(angle, SERVO2_MIN, SERVO2_MAX);

    // Move servo (non-blocking - servo library handles timing)
    servo2.write(angle);
    currentServo2Angle = angle;
}

void centerServo1() {
  setServo1Angle(90);
}

void centerServo2() {
  setServo2Angle(90);
}

void attachServo1() {
  if (!servo1Attached) {
    servo1.attach(SERVO1_PIN);
    servo1.write(currentServo1Angle);
    servo1Attached = true;
    digitalWrite(LED_PIN, HIGH);
  }
}

void attachServo2() {
  if (!servo2Attached) {
    servo2.attach(SERVO2_PIN);
    servo2.write(currentServo2Angle);
    servo2Attached = true;
    digitalWrite(LED_PIN, HIGH);
  }
}

void detachServo1() {
  if (servo1Attached) {
    servo1.detach();
    servo1Attached = false;
  }
}

void detachServo2() {
  if (servo2Attached) {
    servo2.detach();
    servo2Attached = false;
  }
}

// ========
// COMMAND PROCESSING
// ========

void processCommand(String command) {
  command.trim();
  command.toUpperCase();

  // PING command - connectivity test
  if (command == "PING") {
    Serial.println("PONG");
    return;
  }

  // STATUS command - report current state
  if (command == "STATUS") {
    Serial.print("STATUS: Servo1=");
    Serial.print(currentServo1Angle);
    Serial.print("° (Pin 8, Range 40-140°) Attached=");
    Serial.print(servo1Attached ? "YES" : "NO");
    Serial.print(" | Servo2=");
    Serial.print(currentServo2Angle);
    Serial.print("° (Pin 9, Range 40-140°) Attached=");
    Serial.print(servo2Attached ? "YES" : "NO");
    Serial.print(" | Motor1=");
    Serial.print(currentMotor1Speed);
    Serial.print("% | Motor2=");
    Serial.print(currentMotor2Speed);
    Serial.print("% | MD22=");
    Serial.println(md22Available ? "Connected" : "Disconnected");
    return;
  }

  // SERVO1_CENTER command - move servo1 to 90 degrees
  if (command == "SERVO1_CENTER") {
    centerServo1();
    Serial.println("OK: Servo1 centered to 90 degrees");
    return;
  }

  // SERVO2_CENTER command - move servo2 to 90 degrees
  if (command == "SERVO2_CENTER") {
    centerServo2();
    Serial.println("OK: Servo2 centered to 90 degrees");
    return;
  }

  // ALL:M1:{motor1}:M2:{motor2}:S1:{servo1}:S2:{servo2} - Combined command for all actuators with differential drive
  // Example: ALL:M1:60:M2:70:S1:90:S2:110
  if (command.startsWith("ALL:M1:")) {
    // Parse combined command with individual motor speeds
    int m1_pos = command.indexOf(":M1:");
    int m2_pos = command.indexOf(":M2:");
    int s1_pos = command.indexOf(":S1:");
    int s2_pos = command.indexOf(":S2:");

    if (m1_pos != -1 && m2_pos != -1 && s1_pos != -1 && s2_pos != -1) {
      // Extract values
      String motor1Str = command.substring(m1_pos + 4, m2_pos);
      String motor2Str = command.substring(m2_pos + 4, s1_pos);
      String servo1Str = command.substring(s1_pos + 4, s2_pos);
      String servo2Str = command.substring(s2_pos + 4);

      int motor1Speed = motor1Str.toInt();
      int motor2Speed = motor2Str.toInt();
      int servo1Angle = servo1Str.toInt();
      int servo2Angle = servo2Str.toInt();

      // Validate and execute all commands
      bool allValid = true;

      // Validate motor1 (0 or 40-100)
      if (motor1Speed != 0 && (motor1Speed < MOTOR_MIN_PERCENT || motor1Speed > MOTOR_MAX_PERCENT)) {
        allValid = false;
      }

      // Validate motor2 (0 or 40-100)
      if (motor2Speed != 0 && (motor2Speed < MOTOR_MIN_PERCENT || motor2Speed > MOTOR_MAX_PERCENT)) {
        allValid = false;
      }

      // Validate servo1 (40-140)
      if (servo1Angle < SERVO1_MIN || servo1Angle > SERVO1_MAX) {
        allValid = false;
      }

      // Validate servo2 (40-140)
      if (servo2Angle < SERVO2_MIN || servo2Angle > SERVO2_MAX) {
        allValid = false;
      }

      if (allValid) {
        // Execute all commands atomically
        setMotor1Speed(motor1Speed);
        setMotor2Speed(motor2Speed);
        setServo1Angle(servo1Angle);
        setServo2Angle(servo2Angle);

        // ACK: Echo back what was executed (minimal output for debugging)
        Serial.print("OK:M1:");
        Serial.print(motor1Speed);
        Serial.print(":M2:");
        Serial.print(motor2Speed);
        Serial.print(":S1:");
        Serial.print(servo1Angle);
        Serial.print(":S2:");
        Serial.println(servo2Angle);
      } else {
        Serial.print("ERR:RANGE:M1:");
        Serial.print(motor1Speed);
        Serial.print(":M2:");
        Serial.print(motor2Speed);
        Serial.print(":S1:");
        Serial.print(servo1Angle);
        Serial.print(":S2:");
        Serial.println(servo2Angle);
      }
    } else {
      Serial.println("ERROR: ALL command format invalid");
    }
    return;
}

// ALL:M{motor}:S1:{servo1}:S2:{servo2} - Combined command for all actuators (legacy - same speed both motors)
// Example: ALL:M65:S1:90:S2:110
if (command.startsWith("ALL:")) {
  // Parse combined command
  int m_pos = command.indexOf(":M");
  int s1_pos = command.indexOf(":S1:");
  int s2_pos = command.indexOf(":S2:");

    if (m_pos != -1 && s1_pos != -1 && s2_pos != -1) {
      // Extract values
      String motorStr = command.substring(m_pos + 2, s1_pos);
      String servo1Str = command.substring(s1_pos + 4, s2_pos);
      String servo2Str = command.substring(s2_pos + 4);

      int motorSpeed = motorStr.toInt();
      int servo1Angle = servo1Str.toInt();
      int servo2Angle = servo2Str.toInt();

      // Validate and execute all commands
      bool allValid = true;

      // Validate motor (0 or 40-100)
      if (motorSpeed != 0 && (motorSpeed < MOTOR_MIN_PERCENT || motorSpeed > MOTOR_MAX_PERCENT)) {
        allValid = false;
      }

      // Validate servo1 (40-140)
      if (servo1Angle < SERVO1_MIN || servo1Angle > SERVO1_MAX) {
        allValid = false;
      }

      // Validate servo2 (40-140)
      if (servo2Angle < SERVO2_MIN || servo2Angle > SERVO2_MAX) {
        allValid = false;
      }

      if (allValid) {
        // Execute all commands atomically
        setBothMotorsSpeed(motorSpeed);
        setServo1Angle(servo1Angle);
        setServo2Angle(servo2Angle);

        // Single response for all three
        Serial.print("OK:A:M");
        Serial.print(motorSpeed);
        Serial.print(":S1:");
        Serial.print(servo1Angle);
        Serial.print(":S2:");
        Serial.println(servo2Angle);
      } else {
        Serial.println("ERROR: ALL command invalid values");
      }
    } else {
      Serial.println("ERROR: ALL command format invalid");
    }
    return;
}

// Motor stop commands
if (command == "M1_STOP" || command == "MOTOR1_STOP") {
  stopMotor1();
  Serial.println("OK: Motor1 stopped");
  return;
}

if (command == "M2_STOP" || command == "MOTOR2_STOP") {
  stopMotor2();
  Serial.println("OK: Motor2 stopped");
  return;
}

if (command == "STOP_ALL_MOTORS" || command == "STOP_ALL") {
  stopAllMotors();
  Serial.println("OK: All motors stopped");
  return;
}

// SERVO1:angle command - set servo1 to specific angle
if (command.startsWith("SERVO1:")) {
  String angleStr = command.substring(7);
  int angle = angleStr.toInt();

    // Validate angle range for servo1 (40-140)
    if (angle >= SERVO1_MIN && angle <= SERVO1_MAX) {
      setServo1Angle(angle);
      Serial.print("OK:S1:");
      Serial.println(angle);
    } else {
      Serial.print("ERROR: Servo1 angle ");
      Serial.print(angle);
      Serial.print(" out of range (");
      Serial.print(SERVO1_MIN);
      Serial.print("-");
      Serial.print(SERVO1_MAX);
      Serial.println(")");
    }
    return;
}

// SERVO2:angle command - set servo2 to specific angle
if (command.startsWith("SERVO2:")) {
  String angleStr = command.substring(7);
  int angle = angleStr.toInt();

    // Validate angle range for servo2 (40-140)
    if (angle >= SERVO2_MIN && angle <= SERVO2_MAX) {
      setServo2Angle(angle);
      Serial.print("OK:S2:");
      Serial.println(angle);
    } else {
      Serial.print("ERROR: Servo2 angle ");
      Serial.print(angle);
      Serial.print(" out of range (");
      Serial.print(SERVO2_MIN);
      Serial.print("-");
      Serial.print(SERVO2_MAX);
      Serial.println(")");
    }
    return;
}

// MOTOR1:speed command - set motor1 speed (0 or 40-100%)
if (command.startsWith("MOTOR1:") || command.startsWith("M1:")) {
  int colonPos = command.indexOf(':');
  String speedStr = command.substring(colonPos + 1);
  int speed = speedStr.toInt();

    // Allow 0 (stop) or 40-100 range
    if (speed == 0 || (speed >= MOTOR_MIN_PERCENT && speed <= MOTOR_MAX_PERCENT)) {
      setMotor1Speed(speed);
      Serial.print("OK: Motor1 set to ");
      Serial.print(speed);
      Serial.println("%");
    } else {
      Serial.print("ERROR: Motor1 speed ");
      Serial.print(speed);
      Serial.print(" out of range (0 or ");
      Serial.print(MOTOR_MIN_PERCENT);
      Serial.print("-");
      Serial.print(MOTOR_MAX_PERCENT);
      Serial.println("%)");
    }
    return;
}

// MOTOR2:speed command - set motor2 speed (0 or 40-100%)
if (command.startsWith("MOTOR2:") || command.startsWith("M2:")) {
  int colonPos = command.indexOf(':');
  String speedStr = command.substring(colonPos + 1);
  int speed = speedStr.toInt();

    // Allow 0 (stop) or 40-100 range
    if (speed == 0 || (speed >= MOTOR_MIN_PERCENT && speed <= MOTOR_MAX_PERCENT)) {
      setMotor2Speed(speed);
      Serial.print("OK: Motor2 set to ");
      Serial.print(speed);
      Serial.println("%");
    } else {
      Serial.print("ERROR: Motor2 speed ");
      Serial.print(speed);
      Serial.print(" out of range (0 or ");
      Serial.print(MOTOR_MIN_PERCENT);
      Serial.print("-");
      Serial.print(MOTOR_MAX_PERCENT);
      Serial.println("%)");
    }
        return;
    }

    // MOTORS:speed command - set both motors to same speed (0 or 40-100%)
    if (command.startsWith("MOTORS:")) {
      String speedStr = command.substring(7);
      int speed = speedStr.toInt();

        // Allow 0 (stop) or 40-100 range
        if (speed == 0 || (speed >= MOTOR_MIN_PERCENT && speed <= MOTOR_MAX_PERCENT)) {
          setBothMotorsSpeed(speed);
          // Response already sent by setBothMotorsSpeed()
        } else {
          Serial.print("ERROR: Motor speed ");
          Serial.print(speed);
          Serial.print(" out of range (0 or ");
          Serial.print(MOTOR_MIN_PERCENT);
          Serial.print("-");
          Serial.print(MOTOR_MAX_PERCENT);
          Serial.println("%)");
        }
        return;
    }

    // Unknown command
    Serial.print("ERROR: Unknown command: ");
    Serial.println(command);
}

#!/usr/bin/env python3
"""Puente CPM: Quest 3 (WSS) <-> Jetson <-> Arduino (actuadores) + PIC (sensores)."""
import asyncio, ssl, threading, time
import serial, websockets

PUERTO_ACT, BAUD_ACT = "/dev/cpm_actuadores", 115200
PUERTO_SEN, BAUD_SEN = "/dev/cpm_sensores", 9600
VBAT_MIN_MV, TEMP_MAX_D = 11800, 600          # 11.8 V, 60.0     gradosC
PARO_TRAMA = "ALL:M1:0:M2:0:S1:90:S2:90"

estado = {"vbat": None, "temp": None, "paro": False, "t_sen": 0.0, "bloqueo": ""}
lock_act = threading.Lock()
act = serial.Serial(PUERTO_ACT, BAUD_ACT, timeout=0.1)

def enviar_actuadores(linea: str) -> None:
    with lock_act:
        act.write((linea + "\n").encode())

def trama_valida(linea: str):
    """Devuelve (tipo, dict) si el checksum XOR es correcto; si no, None."""
    if not (linea.startswith("$") and "*" in linea):
        return None
    cuerpo, cs = linea[1:].split("*", 1)
    calc = 0
    for c in cuerpo:
        calc ^= ord(c)
    if f"{calc:02X}" != cs.strip()[:2].upper():
        return None
    tipo, *campos = cuerpo.split(",")
    return tipo, dict(c.split("=", 1) for c in campos if "=" in c)

def hilo_sensores() -> None:
    sen = serial.Serial(PUERTO_SEN, BAUD_SEN, timeout=1)
    while True:
        r = trama_valida(sen.readline().decode(errors="ignore").strip())
        if not r:
            continue
        tipo, d = r
        if tipo == "SEN":
            estado["vbat"], estado["temp"] = int(d["VBAT"]), int(d["TEMP"])
            estado["t_sen"] = time.time()
        elif tipo == "EST":
            estado["paro"] = d.get("PARO") == "1"
            if estado["paro"]:
                enviar_actuadores(PARO_TRAMA)          # reacción inmediata, sin esperar al lazo
        elif tipo == "BOOT":
            print("[PIC] reinicio", d)

def motivo_bloqueo() -> str:
    if estado["paro"]:
        return "PARO DE EMERGENCIA"
    if time.time() - estado["t_sen"] > 1.0:
        return "SIN DATOS DEL NODO DE SENSORES"
    if estado["vbat"] is not None and estado["vbat"] < VBAT_MIN_MV:
        return "BATERIA BAJA"
    if estado["temp"] is not None and estado["temp"] > TEMP_MAX_D:
        return "TEMPERATURA ALTA"
    return ""

async def manejador(ws):
    async for msg in ws:
        estado["bloqueo"] = motivo_bloqueo()
        if msg.startswith("ALL:") and estado["bloqueo"]:
            enviar_actuadores(PARO_TRAMA)
            await ws.send(f"BLOQUEADO:{estado['bloqueo']}")
            continue
        if msg.startswith(("ALL:", "MOTORS", "MOTOR1", "MOTOR2", "SERVO2", "STOP")):
            enviar_actuadores(msg)
        # ... MODE2_PATH, MODE2_STOP, poses y análisis: igual que el servidor del capítulo 12

async def main():
    threading.Thread(target=hilo_sensores, daemon=True).start()
    ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
    ctx.load_cert_chain("certs/cert.pem", "certs/key.pem")   # fuera de la carpeta pública
    async with websockets.serve(manejador, "0.0.0.0", 8444, ssl=ctx):
        await asyncio.Future()

if __name__ == "__main__":
    asyncio.run(main())

#!/usr/bin/env python3
"""Servidor HTTPS de archivos para el visor, con carpeta pública y lista blanca."""
import http.server, ssl, os, functools

RAIZ = os.path.join(os.path.dirname(__file__), "publico")   # solo esta carpeta se publica
CERTS = os.path.join(os.path.dirname(__file__), "certs")    # fuera de la raíz, chmod 600
PERMITIDAS = {".html": "text/html", ".js": "application/javascript",
              ".mjs": "application/javascript", ".json": "application/json",
              ".geojson": "application/json", ".glb": "model/gltf-binary",
              ".stl": "model/stl", ".wasm": "application/wasm", ".png": "image/png"}

class Manejador(http.server.SimpleHTTPRequestHandler):
    def guess_type(self, ruta):                       # siempre regresa una cadena
        return PERMITIDAS.get(os.path.splitext(ruta)[1].lower(), "application/octet-stream")
    def send_head(self):
        ext = os.path.splitext(self.path.split("?")[0])[1].lower()
        if self.path not in ("/", "") and ext not in PERMITIDAS:
            self.send_error(404, "No disponible"); return None
        return super().send_head()
    def end_headers(self):
        self.send_header("Cross-Origin-Opener-Policy", "same-origin")
        self.send_header("Cross-Origin-Embedder-Policy", "require-corp")
        super().end_headers()

def main(ip="0.0.0.0", puerto=8443):
    ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
    ctx.load_cert_chain(os.path.join(CERTS, "cert.pem"), os.path.join(CERTS, "key.pem"))
    srv = http.server.ThreadingHTTPServer((ip, puerto), functools.partial(Manejador, directory=RAIZ))
    srv.socket = ctx.wrap_socket(srv.socket, server_side=True)
    print(f"Sirviendo {RAIZ} en https://{ip}:{puerto}")
    srv.serve_forever()

if __name__ == "__main__":
    main()

