// Kalman Filter class
class KalmanFilter {
    constructor(processNoise = 0.01, measurementNoise = 0.25) {
        this.q = processNoise;
        this.r = measurementNoise;
        this.x = 0;
        this.p = 1;
    }
    update(measurement) {
        this.p = this.p + this.q;
        const k = this.p / (this.p + this.r);
        this.x = this.x + k * (measurement - this.x);
        this.p = (1 - k) * this.p;
        return this.x;
    }
}
const kfX = new KalmanFilter(0.01, 0.1); // Position: moderate smoothing
