// --------
// [CORRECCION] Convencion unica de direccion (modos 2 y 5)
//   Rumbo al objetivo: psi* = atan2(dx, dz) (0 = +Z, crece al girar a la izq.)
//   Rumbo del control: yaw del cuaternion (0 = -Z, crece al girar a la izq.)
//   Ambos crecen en el mismo sentido pero sus ceros difieren en PI; por eso
//   el rumbo del vehiculo es yaw + PI. Sin esta conversion el error vale
//   e + PI, la direccion queda saturada y se "corregia" invirtiendo el signo
//   (S2 = 90 - k*delta), que dejaba al vehiculo en control todo-nada.
// --------
const MONTAJE_RAD = 0;           // control montado mirando al frente del vehiculo
function envolverPi(a) { while (a > Math.PI) a -= 2*Math.PI; while (a < -Math.PI) a += 2*Math.PI; return a; }
function rumboVehiculo(yawRad) { return envolverPi(yawRad + Math.PI + MONTAJE_RAD); }
function anguloAServo(deltaDeg, k, sMin, sMax) {    // delta > 0 = izquierda
    return Math.max(sMin, Math.min(sMax, Math.round(90 + deltaDeg * k)));
}
// Error lateral con signo (> 0 si el vehiculo esta a la IZQUIERDA del tramo A->B)
function errorLateral(ax, az, bx, bz, px, pz) {
    const dx = bx - ax, dz = bz - az, L = Math.hypot(dx, dz) || 1e-6;
    return (dz * (px - ax) - dx * (pz - az)) / L;
}

