function sendManualControlCommand() {
    if (!isManualControlActive || !websocket || websocket.readyState !== WebSocket.OPEN) return;

    // Calculate base motor speed from joystick
    const baseSpeed = Math.round(lastMotorSpeed);
    const servo1Angle = Math.round(lastServo1);
    const servo2Angle = Math.round(lastServo2);

    // DIFFERENTIAL DRIVE LOGIC - Ackermann Geometry Based
    let motor1Speed = baseSpeed; // [CORRECCION] M1 = motor IZQUIERDO
    let motor2Speed = baseSpeed; // [CORRECCION] M2 = motor DERECHO

    // Vehicle geometry (cm)
    const WHEELBASE = 34;        // Front to rear wheel distance
    const TRACK_WIDTH = 29;      // Left to right wheel center distance

    // Trigger thresholds
    const SPEED_THRESHOLD = 55;          // Apply differential only above 55%
    const MIN_STEERING_ANGLE = 10;       // Minimum 10° turn to trigger

    // Servo to steering angle mapping (linear approximation)
    // Servo 90° = 0° steering
    // Servo 130° = 30° left (inner wheel angle)
    // Servo 50° = 30° right (inner wheel angle)
    const servoToAngle = (servo) => {
        // Map servo range to steering angle
        // 90 -> 0°, 130 -> 30°, 50 -> -30°
        return (servo - 90) * (30 / 40); // 40° servo range = 30° wheel angle
    };

    const steeringAngle = servoToAngle(servo2Angle);    // Positive = left, negative = right

    if (baseSpeed >= SPEED_THRESHOLD && Math.abs(steeringAngle) >= MIN_STEERING_ANGLE) {
        // Calculate turn radius from Ackermann geometry
        const innerAngleDeg = Math.abs(steeringAngle);
        const innerAngleRad = innerAngleDeg * Math.PI / 180;

        // Turn radius from vehicle center
        const turnRadius = WHEELBASE / Math.tan(innerAngleRad);

        // Inner and outer wheel radii
        const innerRadius = turnRadius - (TRACK_WIDTH / 2);
        const outerRadius = turnRadius + (TRACK_WIDTH / 2);

        // Speed ratio (outer/inner)
        const speedRatio = outerRadius / innerRadius;

        // Calculate differential percentage using selected mode
        // differentialMode: 0.25 = 25%, 0.50 = 50%, 0.75 = 75%
        const fullDifferential = ((speedRatio - 1) / 2) * 100; // Convert to percentage
        const differentialMode = window.differentialMode || 0.25; // Default 0.25
        const differential = fullDifferential * differentialMode;

        // [CORRECCION] Giro a la izquierda (servo > 90): M1 (izquierdo) es la
        // rueda interior y va mas lento; a la derecha, M2 (derecho) es interior.
        const vInt = baseSpeed - differential, vExt = baseSpeed + differential;
        if (steeringAngle > 0) { motor1Speed = vInt; motor2Speed = vExt; }
        else                   { motor1Speed = vExt; motor2Speed = vInt; }
        // Rango valido del firmware en modo 1: 0 o 50-80 %
        motor1Speed = Math.round(Math.max(50, Math.min(80, motor1Speed)));
        motor2Speed = Math.round(Math.max(50, Math.min(80, motor2Speed)));
    }

