        // Convert to cm relative to map center
        leftX_cm = ((leftX - userX) / MAP_SIZE * 200);
        leftZ_cm = ((leftZ - userZ) / MAP_SIZE * 200);
        leftY_cm = (leftY - floorY) * 100; // cm above floor

        // Get all three headings for analysis
        controllerHeading_deg = window.mode1ControllerHeading || 0;
        travelHeading_deg = window.mode1TravelHeading || controllerHeading_deg;
        finalHeading_deg = window.mode1FinalHeading || 0;
    }

    // Send COMBINED command with differential speeds AND position data
    const timestamp = performance.now() / 1000;
    websocket.send(`TRACK:${timestamp.toFixed(3)}:${leftX_cm.toFixed(1)}:${leftY_cm.toFixed(1)}:${leftZ_cm.toFixed(1)}:${controllerHeading_deg.toFixed

    // STORE Mode 1 position/heading for Mode 2 option (if robot is moving)
    if (baseSpeed > 0 && mode0Robot && mode0Robot.visible) {
        mode1LastPosition = {
            x: mode0Robot.position.x,
            y: mode0Robot.position.y,
            z: mode0Robot.position.z
        };
        mode1LastHeading = mode0Robot.rotation.y; // radians
        mode1WasUsed = true; // Enable Mode 1 option in Mode 2 UI
    }

    // Debug log occasionally (every 5 seconds) - show steering angle and differential
    if (Math.random() < 0.1) {
