        }
    }
}

function sendStopCommand() {
    lastJoystickForward = 0;
    lastJoystickTurn = 0;
    lastMotorSpeed = 0;
    lastServo2 = 90; // Center steering
    lastServo1 = 90; // Center gripper

    if (websocket && websocket.readyState === WebSocket.OPEN) {
        websocket.send('ALL:M1:0:M2:0:S1:90:S2:90');
        debugLog('Mode 1: STOP command sent', 'INFO');
    }
}

function processJoystickInput(forwardAxis, turnAxis) {
    // Dead zone (15%)
    const DEAD_ZONE = 0.15;

    // Apply dead zone
    const forward = Math.abs(forwardAxis) > DEAD_ZONE ? forwardAxis : 0;
    const turn = Math.abs(turnAxis) > DEAD_ZONE ? turnAxis : 0;

    lastJoystickForward = forward;
    lastJoystickTurn = turn;

    // Map forward to motor speed: 0 or 50-80% (Arduino requirement)
    // ONLY ACCEPT POSITIVE (FORWARD) VALUES - ignore backward joystick
    if (forward > 0) {
        // Scale: 0.0-1.0 input -> 50-80% output
        lastMotorSpeed = 50 + (forward * 30); // 50 + (0-30) = 50-80
    } else {
        lastMotorSpeed = 0; // Stop (backward ignored, centered = stop)
    }

    // Map turn (-1 to +1) to servo2 angle (50° to 130°)
    // MAX STEERING when joystick is 75%+ to either side
    if (turn <= -0.75) {
        // FULL LEFT
        lastServo2 = 130; // MAX left turn
    } else if (turn >= 0.75) {
        // FULL RIGHT
        lastServo2 = 50;   // MAX right turn
    } else {
        // Normal steering mapping
        // -1 = full left -> 130° (LEFT turn)
        // 0 = straight -> 90° (STRAIGHT)
        // +1 = full right -> 50° (RIGHT turn)
        lastServo2 = 90 - (turn * 40); // NEGATED to fix inversion
        lastServo2 = Math.max(50, Math.min(130, lastServo2)); // Clamp to range
    }
}

function processGripperButtons(aPressed, bPressed) {
    // A button: open gripper (40°)
    // B button: close gripper (140°)

    if (aPressed) {
        lastServo1 = 40; // Open
        debugLog('Gripper: OPEN (40°)', 'INFO');
    } else if (bPressed) {
        lastServo1 = 140; // Close
        debugLog('Gripper: CLOSE (140°)', 'INFO');
    }
}

function mode2ControlLoop() {
    if (!mode2Following) return;

    // SAFETY: Check timeout
    if (Date.now() - mode2StartTime > MODE2_MAX_DURATION) {
        debugLog('Mode 2: TIMEOUT - stopped after 2 minutes', 'ERROR');
        stopMode2Following();
        return;
    }

    // Update robot position from selected tracking source (10Hz sampling via RAF)
    if (mode2TrackingSource === 'controller') {
        if (window.mode4Position && window.mode4Heading !== null) {
            mode2RobotPosition.set(
                window.mode4Position.x,
                window.mode4Position.y,
                window.mode4Position.z
            );
            mode2RobotHeading = window.mode4Heading;
            window.mode2RobotHeading = mode2RobotHeading; // Expose for visual marker
        } else {
            debugLog('Mode 2: WARNING - Controller tracking lost!', 'WARN');
        }
    } else if (mode2TrackingSource === 'mode1') {
        // Mode 1 tracking is static (doesn't update during execution)
        // Position updates would come from odometry if we had it
    }

    // Check if we've completed all waypoints
    if (mode2CurrentWaypointIndex >= mode2PathToFollow.length) {
        debugLog(`Mode 2: [OK] COMPLETED - Reached all ${mode2PathToFollow.length} waypoints`, 'INFO');
        stopMode2Following();
        return;
    }

    // Get current target waypoint
    const targetWaypoint = mode2PathToFollow[mode2CurrentWaypointIndex];

    // Calculate distance to current waypoint
    const dx = targetWaypoint.x - mode2RobotPosition.x;
    const dz = targetWaypoint.z - mode2RobotPosition.z;
    const distanceToWaypoint = Math.sqrt(dx * dx + dz * dz);

    // Check if we've reached the current waypoint (10cm tolerance)
    if (distanceToWaypoint < 0.10) { // 10cm threshold
        debugLog(`Mode 2: [OK] Waypoint ${mode2CurrentWaypointIndex + 1}/${mode2PathToFollow.length} reached (${(distanceToWaypoint * 100).toFixed(1)}
        mode2CurrentWaypointIndex++;

        // Check if that was the last waypoint
        if (mode2CurrentWaypointIndex >= mode2PathToFollow.length) {
            debugLog('Mode 2: [OK] ALL WAYPOINTS REACHED - Stopping', 'INFO');
            stopMode2Following();
            return;
        }
    }

    // Calculate path deviation (distance to nearest path segment)
    let pathDeviation = Infinity;
    for (let i = 0; i < mode2PathToFollow.length - 1; i++) {
        const p1 = mode2PathToFollow[i];
        const p2 = mode2PathToFollow[i + 1];

        // Distance from point to line segment
        const segDx = p2.x - p1.x;
        const segDz = p2.z - p1.z;
        const segLenSq = segDx * segDx + segDz * segDz;

        if (segLenSq === 0) continue;

        let t = ((mode2RobotPosition.x - p1.x) * segDx + (mode2RobotPosition.z - p1.z) * segDz) / segLenSq;
        t = Math.max(0, Math.min(1, t));

        const projX = p1.x + t * segDx;
        const projZ = p1.z + t * segDz;
        const dist = Math.sqrt((mode2RobotPosition.x - projX) ** 2 + (mode2RobotPosition.z - projZ) ** 2);

        if (dist < pathDeviation) {
            pathDeviation = dist;
        }
    }

    // Log warning if too far from path
    if (pathDeviation > 0.10) { // 10cm deviation tolerance
        debugLog(`Mode 2: WARNING - Path deviation: ${(pathDeviation * 100).toFixed(1)}cm (max 10cm)`, 'WARN');
    }

    // 5 Hz COMMAND RATE: only send commands every 200 ms
    const now = Date.now();
    if (now - mode2LastCommandTime < MODE2_COMMAND_INTERVAL) {
        // Not time to send command yet, just update visualization
        updateMode2Visualization();
        requestAnimationFrame(mode2ControlLoop);
        return;
    }

    mode2LastCommandTime = now;

    // [CORRECCION] Rumbo al objetivo y rumbo del vehiculo en el mismo marco
    const targetHeading = Math.atan2(dx, dz);
    const psiV = rumboVehiculo(mode2RobotHeading);
    const headingError = envolverPi(targetHeading - psiV);

    // Angulo de direccion (+ = izquierda), saturado a +-30 grados
    const steeringAngleDeg = Math.max(-30, Math.min(30, headingError * 180 / Math.PI));
    const clampedServo2 = anguloAServo(steeringAngleDeg, 40 / 30, 50, 130);

    // Velocidad base segun curvatura (55-70 %)
    const curvature = Math.abs(headingError) / Math.max(distanceToWaypoint, 0.01);
    let baseSpeed = Math.round(Math.max(55, Math.min(70, 70 - curvature * 200)));

    // [CORRECCION] Diferencial: rueda interior = base*lambda con minimo de 50 %;
    // si se recorta a 50, la exterior sube a min(80, 50/lambda). M1 = izquierdo.
    const lam = window.differentialMode || 0.25;
    let vInt = Math.round(baseSpeed * lam), vExt = baseSpeed;
    if (vInt < 50) { vInt = 50; vExt = Math.min(80, Math.round(50 / lam)); }
    let motor1Speed = baseSpeed, motor2Speed = baseSpeed;
    if (steeringAngleDeg > 3)       { motor1Speed = vInt; motor2Speed = vExt; } // izquierda
    else if (steeringAngleDeg < -3) { motor1Speed = vExt; motor2Speed = vInt; } // derecha

    // [CORRECCION] Un solo mensaje por ciclo: el servidor arma la trama ALL a
    // partir de MODE2_TRACK (antes se enviaban ALL y MODE2_TRACK y el Arduino
    // recibia cada comando dos veces).
    if (websocket && websocket.readyState === WebSocket.OPEN) {
        const timestamp = Date.now();
        const headingDeg = (psiV * 180 / Math.PI + 360) % 360;
        const targetHeadingDeg = (targetHeading * 180 / Math.PI + 360) % 360;
        const posX_cm = (mode2RobotPosition.x * 100).toFixed(1);
        const posZ_cm = (mode2RobotPosition.z * 100).toFixed(1);
        const distNext_cm = (distanceToWaypoint * 100).toFixed(1);
        const pathDev_cm = (pathDeviation * 100).toFixed(1);
        const trackCommand = `MODE2_TRACK:${timestamp}:${posX_cm}:0:${posZ_cm}:${headingDeg.toFixed(0)}:${targetHeadingDeg.toFixed(0)}:${distNext_cm}:
        websocket.send(trackCommand);
    }

    // Update visualization
    updateMode2Visualization();

    // Continue loop
    requestAnimationFrame(mode2ControlLoop);
}

// ========
// [RECONSTRUIDO] MODO 5: seguimiento autonomo del anillo M25 suavizado.
// Rehecho a partir del reporte del proyecto (corrida final: SPLINE, R = 45 cm,
// escala 110 %, 28/28 puntos de paso a 20 cm, 0 errores del Arduino).
// ========
const M5_K_SERVO   = 50 / 30;   // +-30 grados de ruedas -> 40-140 en el servo
const M5_K_STANLEY = 2.0;       // ganancia del termino lateral
const M5_V_REF     = 0.5;       // m/s, velocidad de referencia de Stanley
const M5_CT_MAX    = 15;        // grados, tope del termino lateral
const M5_ABORTO    = 0.80;      // m: abortar si el punto de paso queda a > 80 cm
const M5_INICIO    = 0.20;      // m: tolerancia para colocar el vehiculo en el cono
const M5_GUARDA    = 0.80;      // fraccion: el anillo empieza y termina igual

function startMode5Following() {
    if (!mode5SmoothedPath || mode5SmoothedPath.length < 3) {
        debugLog('Mode 5: Smooth path first', 'ERROR');
        return;
    }
    const p0 = mode5SmoothedPath[0], pos = window.mode4Position;
    if (!pos || Math.hypot(p0.x - pos.x, p0.z - pos.z) > M5_INICIO) {
        debugLog('Mode 5: coloque el vehiculo en el cono magenta (< 20 cm)', 'WARN');
        return;
    }
    mode5PathToFollow = mode5SmoothedPath;
    mode5CurrentWaypointIndex = 0;
    mode5TrackingActive = true;      // la pose del control se actualiza cada cuadro
    mode5Following = true;
    mode5LastCommandTime = 0;
    if (websocket) websocket.send(`MODE5_PATH:${JSON.stringify({
        waypoints: mode5PathToFollow.map(p => [p.x, p.z]), radius: mode5TurningRadius })}`);
    debugLog(`Mode 5: Following started (${mode5PathToFollow.length} waypoints, 5 Hz)`, 'INFO');
    requestAnimationFrame(mode5ControlLoop);
}

function stopMode5Following(motivo) {
    mode5Following = false;
    mode5TrackingActive = false;
    if (websocket && websocket.readyState === WebSocket.OPEN) {
        websocket.send('MODE5_STOP');           // el servidor manda el paro al Arduino
    }
    debugLog(`Mode 5: STOP (${motivo})`, 'WARN');
}

function mode5ControlLoop() {
    if (!mode5Following || !mode5PathToFollow) return;
    const pos = window.mode4Position;
    if (!pos || window.mode4Heading === null) { requestAnimationFrame(mode5ControlLoop); return; }

    const N = mode5PathToFollow.length;
    const i = mode5CurrentWaypointIndex;
    const target = mode5PathToFollow[i];
    const dist = Math.hypot(target.x - pos.x, target.z - pos.z);

    // Avance de punto de paso (10 cm); el ultimo se acepta a 20 cm y solo
    // despues de recorrer el 80 % del anillo (inicio = fin)
    const ultimo = (i === N - 1);
    if ((!ultimo && dist < 0.10) || (ultimo && i >= M5_GUARDA * N && dist < 0.20)) {
        mode5CurrentWaypointIndex++;
        if (mode5CurrentWaypointIndex >= N) { stopMode5Following('vuelta completa'); return; }
        requestAnimationFrame(mode5ControlLoop);
        return;
    }
    if (dist > M5_ABORTO) { stopMode5Following('desviacion > 80 cm'); return; }

    const now = Date.now();
    if (now - mode5LastCommandTime < MODE5_COMMAND_INTERVAL) {     // 5 Hz
        requestAnimationFrame(mode5ControlLoop);
        return;
    }
    mode5LastCommandTime = now;

    // Termino de rumbo (marco comun) + termino lateral de Stanley
    const psiV = rumboVehiculo(window.mode4Heading);
    const ePsi = envolverPi(Math.atan2(target.x - pos.x, target.z - pos.z) - psiV);
    const prev = mode5PathToFollow[Math.max(0, i - 1)];
    const eLat = errorLateral(prev.x, prev.z, target.x, target.z, pos.x, pos.z);
    let ctDeg = -Math.atan(M5_K_STANLEY * eLat / M5_V_REF) * 180 / Math.PI;
    ctDeg = Math.max(-M5_CT_MAX, Math.min(M5_CT_MAX, ctDeg));
    const deltaDeg = Math.max(-30, Math.min(30, ePsi * 180 / Math.PI + ctDeg));
    const s2 = anguloAServo(deltaDeg, M5_K_SERVO, 40, 140);

    // Velocidades: 85/85 en recta; en el giro maximo 100 (exterior) / 50 (interior)
    const f = Math.abs(deltaDeg) / 30;
    const vExt = Math.round(85 + 15 * f), vInt = Math.round(85 - 35 * f);
    let m1 = 85, m2 = 85;
    if (deltaDeg > 0.5)       { m1 = vInt; m2 = vExt; }    // izquierda: M1 interior
    else if (deltaDeg < -0.5) { m1 = vExt; m2 = vInt; }    // derecha:   M2 interior

    if (websocket && websocket.readyState === WebSocket.OPEN) {
        const dev = Math.abs(eLat) * 100;
        websocket.send(`MODE5_TRACK:${now}:${(pos.x*100).toFixed(1)}:0:${(pos.z*100).toFixed(1)}:` +
            `${((psiV*180/Math.PI)+360)%360|0}:${deltaDeg.toFixed(0)}:${(dist*100).toFixed(1)}:` +
            `${dev.toFixed(1)}:WP:${i + 1}/${N}:M1:${m1}:M2:${m2}:S2:${s2}`);
    }
    requestAnimationFrame(mode5ControlLoop);
}

// Mode 4: Track left controller with Kalman (ALSO used by Mode 2!)
if (source.handedness === 'left' && (isTrackingRobot || mode2TrackingActive || mode5TrackingActive) && source.gripSpace && !source.hand) {
    const gripPose = frame.getPose(source.gripSpace, refSpace);
    if (gripPose) {
        const pos = gripPose.transform.position;
        const ori = gripPose.transform.orientation;

        // POSITION: Direct from controller (absolute floor coordinates)
        const controllerX = pos.x;
        const controllerZ = pos.z;
        const controllerY = pos.y;

        // ROTATION: Unwrap angles to prevent 180° jumps
        const qx = ori.x, qy = ori.y, qz = ori.z, qw = ori.w;
        const rawHeading = Math.atan2(2*(qw*qy + qx*qz), 1 - 2*(qy*qy + qz*qz));
        const rawDeg = rawHeading * 180 / Math.PI;

        // Unwrap: handle -180/+180 boundary
        let unwrappedDeg = rawDeg;
        if (mode4FirstFrame) {
            lastUnwrappedHeading = rawDeg;
        } else {
            const delta = rawDeg - (lastUnwrappedHeading % 360);
            if (delta > 180) {
                 unwrappedDeg = lastUnwrappedHeading + (delta - 360);
            } else if (delta < -180) {
                 unwrappedDeg = lastUnwrappedHeading + (delta + 360);
            } else {
                 unwrappedDeg = lastUnwrappedHeading + delta;
            }
        }
        lastUnwrappedHeading = unwrappedDeg;

        // Kalman filter on UNWRAPPED angle
        const fx = kfX.update(controllerX);
        const fz = kfZ.update(controllerZ);
        const filtHeadingDeg = kfH.update(unwrappedDeg);
        const filtHeadingRad = (filtHeadingDeg % 360) * Math.PI / 180;

        // EXPOSE Mode 4 tracking data globally (for Mode 2 to use)
        window.mode4Position = { x: fx, y: controllerY, z: fz };
        window.mode4Heading = filtHeadingRad; // radians

        if (mode4FirstFrame) {
            mode4FirstFrame = false;
            debugLog(`Mode 4: Controller detected at (${fx.toFixed(2)}, ${fz.toFixed(2)}), heading: ${filtHeadingDeg.toFixed(1)}°`, 'INFO'
        }

        // Update triangle marker (controller position in air)
        if (triangleMarker) {
            triangleMarker.position.set(fx, controllerY, fz);
            triangleMarker.rotation.y = filtHeadingRad;
        }

        // Update green cone icon
        if (robotIcon) {
            robotIcon.position.set(fx, floorY + 0.20, fz);
            robotIcon.rotation.y = filtHeadingRad;
        }

        // CRITICAL: Vehicle position = Controller position (NO offsets, NO anchoring)
        const vehicleX = fx;
        const vehicleZ = fz;
        const vehicleY = floorY + 0.045; // 4.5cm wheel offset
        const vehicleHeading = filtHeadingRad + (Math.PI / 2); // Model orientation offset

        // Update ROBOT
        if (currentVehicle === 'robot' && mode0Robot) {
            mode0Robot.position.set(vehicleX, vehicleY, vehicleZ);
            mode0Robot.rotation.y = vehicleHeading;

            if (!mode0Robot.visible) {
                mode0Robot.visible = true;
                debugLog('Mode 4: Robot VISIBLE at controller position', 'INFO');
            }
        }

        // Update TRUCK
        if (currentVehicle === 'truck' && mode0Truck) {
            mode0Truck.position.set(vehicleX, vehicleY, vehicleZ);
            mode0Truck.rotation.y = vehicleHeading;

            if (!mode0Truck.visible) {
                mode0Truck.visible = true;
                debugLog('Mode 4: Truck VISIBLE at controller position', 'INFO');
            }
        }

        // Chart uses RELATIVE distance from user start position for display only
        const dist_cm = Math.sqrt((fx - userX)**2 + (fz - userZ)**2) / MAP_SIZE * 200;
        updateRobotChart(performance.now() / 1000, dist_cm, filtHeadingDeg % 360);
    }
}
